import type { createServer, IncomingMessage } from "node:http";
import type { AddressInfo } from "node:net";
import { type WebSocket, WebSocketServer } from "ws";
import type { ResolvedHubRolesConfig } from "./config.ts";
import { HubAdmin } from "./hub-admin.ts";
import { type HubClientMessage, isHubScopedMessage } from "./protocol.ts";
import type { Room } from "./room.ts";
import type { RoomManager } from "./room-manager.ts";
import { RoomRegistryError } from "./room-registry.ts";

export interface WsHubOptions {
	token: string;
	roomManager: RoomManager;
	defaultRoomId: string;
	rolesConfig: ResolvedHubRolesConfig;
	cwd: string;
}

export class WsHub {
	private readonly wss: WebSocketServer;
	private readonly server: ReturnType<typeof createServer>;
	private readonly options: WsHubOptions;
	private readonly admin: HubAdmin;

	constructor(server: ReturnType<typeof createServer>, options: WsHubOptions) {
		this.server = server;
		this.options = options;
		this.admin = new HubAdmin({
			token: options.token,
			roomManager: options.roomManager,
			rolesConfig: options.rolesConfig,
			cwd: options.cwd,
		});
		this.wss = new WebSocketServer({ noServer: true });

		this.server.on("upgrade", (request, socket, head) => {
			if (!this.isWebSocketPath(request)) {
				socket.destroy();
				return;
			}
			this.wss.handleUpgrade(request, socket, head, (ws) => {
				this.wss.emit("connection", ws, request);
			});
		});

		this.wss.on("connection", (ws) => {
			ws.on("message", (data) => {
				void this.onMessage(ws, data).catch((err) => {
					const message = err instanceof Error ? err.message : String(err);
					this.send(ws, { type: "error", code: "internal", message });
				});
			});
		});
	}

	getAddress(): AddressInfo | string | null {
		return this.server.address();
	}

	private isWebSocketPath(request: IncomingMessage): boolean {
		const url = new URL(request.url ?? "/", "http://localhost");
		return url.pathname === "/ws" || url.pathname === "/ws/";
	}

	private async onMessage(ws: WebSocket, data: unknown): Promise<void> {
		let parsed: HubClientMessage;
		try {
			const text = typeof data === "string" ? data : data instanceof Buffer ? data.toString("utf8") : "";
			parsed = JSON.parse(text) as HubClientMessage;
		} catch {
			this.send(ws, { type: "error", code: "invalid_json", message: "Invalid JSON message" });
			return;
		}

		if (isHubScopedMessage(parsed)) {
			await this.admin.handle(ws, parsed);
			return;
		}

		if (parsed.type === "join") {
			await this.handleJoin(ws, parsed);
			return;
		}

		if (parsed.type === "leave") {
			this.handleLeave(ws);
			return;
		}

		const room = (ws as WebSocket & { __piRoom?: Room }).__piRoom;
		const client = (ws as WebSocket & { __piClient?: { id: string; displayName: string } }).__piClient;
		if (!room || !client) {
			this.send(ws, { type: "error", code: "not_joined", message: "Send join before other commands" });
			return;
		}

		const bound = room.getClient(client.id);
		if (!bound) {
			this.send(ws, { type: "error", code: "not_joined", message: "Client not registered" });
			return;
		}

		await room.handleMessage(bound, parsed);
	}

	private async handleJoin(ws: WebSocket, message: Extract<HubClientMessage, { type: "join" }>): Promise<void> {
		if ((ws as WebSocket & { __piRoom?: Room }).__piRoom) {
			this.send(ws, { type: "error", code: "already_joined", message: "Already joined" });
			return;
		}

		const clientToken = message.token.trim();
		const serverToken = this.options.token.trim();
		if (clientToken !== serverToken) {
			this.send(ws, {
				type: "error",
				code: "unauthorized",
				message:
					"Invalid token. Use the token the running pi-hub process expects (from .pi/hub.json, or PI_HUB_TOKEN if set in that shell).",
			});
			ws.close(4401, "unauthorized");
			return;
		}

		try {
			const roomId = message.roomId.trim() || this.options.defaultRoomId;
			console.log(`[pi-hub] Join room=${roomId} as ${message.displayName}`);
			const room = await this.options.roomManager.getOrCreateRoom(roomId);
			const client = room.addClient(ws, message.displayName);

			const tagged = ws as WebSocket & {
				__piRoom?: Room;
				__piClient?: { id: string; displayName: string };
				__piOnClose?: () => void;
			};
			tagged.__piOnClose?.();
			const onClose = () => {
				room.removeClient(client.id);
			};
			tagged.__piOnClose = onClose;
			tagged.__piRoom = room;
			tagged.__piClient = {
				id: client.id,
				displayName: client.displayName,
			};

			room.sendJoined(client);

			ws.on("close", onClose);
		} catch (err) {
			const code = err instanceof RoomRegistryError ? err.code : "join_failed";
			const messageText = err instanceof Error ? err.message : String(err);
			console.error(`[pi-hub] Join failed:`, err);
			this.send(ws, {
				type: "error",
				code,
				message: messageText,
			});
			ws.close(1011, "join failed");
		}
	}

	private handleLeave(ws: WebSocket): void {
		const tagged = ws as WebSocket & {
			__piRoom?: Room;
			__piClient?: { id: string; displayName: string };
			__piOnClose?: () => void;
		};
		const room = tagged.__piRoom;
		const clientMeta = tagged.__piClient;
		if (!room || !clientMeta) {
			this.send(ws, { type: "error", code: "not_joined", message: "Not in a room" });
			return;
		}
		const roomId = room.roomId;
		room.removeClient(clientMeta.id);
		tagged.__piOnClose = undefined;
		delete tagged.__piRoom;
		delete tagged.__piClient;
		this.send(ws, { type: "left", roomId });
	}

	private send(ws: WebSocket, message: object): void {
		if (ws.readyState === ws.OPEN) {
			ws.send(JSON.stringify(message));
		}
	}
}

import { existsSync, readFileSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import {
	AuthStorage,
	type CreateAgentSessionResult,
	createAgentSession,
	getAgentDir,
	ModelRegistry,
	SessionManager,
} from "@earendil-works/pi-coding-agent";
import type { ResolvedHubModelsConfig, ResolvedHubRolesConfig } from "./config.ts";
import { Room } from "./room.ts";
import { RoomRegistry, RoomRegistryError } from "./room-registry.ts";

export interface RoomManagerOptions {
	cwd: string;
	agentDir?: string;
	/** Legacy: single session file shared by all rooms (discouraged). */
	sessionPath?: string;
	defaultRoomId?: string;
	modelsConfig: ResolvedHubModelsConfig;
	rolesConfig: ResolvedHubRolesConfig;
	registry?: RoomRegistry;
	/** Test hook: override default createAgentSession */
	createSession?: (
		roomId: string,
		cwd: string,
		agentDir: string,
		sessionFile: string,
	) => Promise<CreateAgentSessionResult>;
}

export class RoomManager {
	private readonly rooms = new Map<string, Room>();
	private readonly roomInit = new Map<string, Promise<Room>>();
	private readonly options: RoomManagerOptions;
	readonly registry: RoomRegistry;

	constructor(options: RoomManagerOptions) {
		this.options = options;
		this.registry = options.registry ?? new RoomRegistry(options.cwd);
	}

	/** Ensure default room exists in registry at startup. */
	initialize(defaultRoomId: string): void {
		this.registry.ensureDefaultRoom(defaultRoomId);
	}

	listRooms(): ReturnType<RoomRegistry["listRooms"]> {
		return this.registry.listRooms();
	}

	createRoom(roomId: string, title?: string) {
		return this.registry.createRoom(roomId, { title });
	}

	async deleteRoom(roomId: string, options?: { deleteFiles?: boolean }): Promise<void> {
		const room = this.rooms.get(roomId);
		if (room) {
			await room.stop();
			this.rooms.delete(roomId);
		}
		this.roomInit.delete(roomId);
		this.registry.deleteRoom(roomId, options);
	}

	getActiveRoom(roomId: string): Room | undefined {
		return this.rooms.get(roomId);
	}

	async getOrCreateRoom(roomId: string): Promise<Room> {
		if (!this.registry.hasRoom(roomId)) {
			throw new RoomRegistryError(
				`Room "${roomId}" not found. Create it with create_room before joining.`,
				"room_not_found",
			);
		}

		const existing = this.rooms.get(roomId);
		if (existing) {
			return existing;
		}

		let init = this.roomInit.get(roomId);
		if (!init) {
			init = this.createRoomInstance(roomId);
			this.roomInit.set(roomId, init);
		}

		const room = await init;
		this.rooms.set(roomId, room);
		this.roomInit.delete(roomId);
		return room;
	}

	async shutdown(): Promise<void> {
		for (const room of this.rooms.values()) {
			await room.stop();
		}
		this.rooms.clear();
		this.roomInit.clear();
	}

	private async createRoomInstance(roomId: string): Promise<Room> {
		const sessionResult = await this.createSessionForRoom(roomId);
		const roomConfig = this.registry.loadRoomConfig(roomId);
		const room = new Room({
			roomId,
			sessionResult,
			cwd: resolve(this.options.cwd),
			rolesConfig: this.options.rolesConfig,
			modelsConfig: this.options.modelsConfig,
			roomConfig,
			registry: this.registry,
		});
		await room.start();
		await room.applyConfiguredSessionModel();
		return room;
	}

	private async createSessionForRoom(roomId: string): Promise<CreateAgentSessionResult> {
		const cwd = resolve(this.options.cwd);
		const agentDir = this.options.agentDir ?? getAgentDir();

		if (this.options.createSession) {
			const sessionFile = this.registry.getSessionPath(roomId);
			return this.options.createSession(roomId, cwd, agentDir, sessionFile);
		}

		if (this.options.sessionPath) {
			const sessionFile = resolve(this.options.sessionPath);
			const sessionManager = SessionManager.open(sessionFile, undefined, cwd);
			const authStorage = AuthStorage.create(agentDir ? join(agentDir, "auth.json") : undefined);
			const modelRegistry = ModelRegistry.create(authStorage, agentDir ? join(agentDir, "models.json") : undefined);
			return createAgentSession({
				cwd,
				agentDir,
				authStorage,
				modelRegistry,
				sessionManager,
			});
		}

		const sessionFile = this.registry.getSessionPath(roomId);
		const sessionDir = resolve(sessionFile, "..");

		let sessionManager: SessionManager;
		if (hasSessionContent(sessionFile)) {
			sessionManager = SessionManager.open(sessionFile, undefined, cwd);
		} else {
			sessionManager = SessionManager.create(cwd, sessionDir);
			const actualFile = sessionManager.getSessionFile();
			if (actualFile && actualFile !== sessionFile) {
				this.registry.updateSessionFile(roomId, actualFile);
			}
		}

		const authStorage = AuthStorage.create(agentDir ? join(agentDir, "auth.json") : undefined);
		const modelRegistry = ModelRegistry.create(authStorage, agentDir ? join(agentDir, "models.json") : undefined);

		return createAgentSession({
			cwd,
			agentDir,
			authStorage,
			modelRegistry,
			sessionManager,
		});
	}
}

function hasSessionContent(path: string): boolean {
	try {
		if (!existsSync(path)) {
			return false;
		}
		const st = statSync(path);
		if (!st.isFile()) {
			return false;
		}
		return readFileSync(path, "utf8").trim().length > 0;
	} catch {
		return false;
	}
}

import type { AgentSession, AgentSessionEvent, CreateAgentSessionResult } from "@earendil-works/pi-coding-agent";
import type { WebSocket } from "ws";
import type { ResolvedHubModelsConfig, ResolvedHubRolesConfig } from "./config.ts";
import { ExtensionUiRouter } from "./extension-ui.ts";
import { resolveMessageMentions } from "./mentions.ts";
import { listHubModels } from "./model-info.ts";
import {
	applyRoleModelOverrides,
	buildRoleModelEntries,
	parseModelRef,
	persistRoleModelOverride,
} from "./models-config.ts";
import { PromptQueue } from "./prompt-queue.ts";
import type {
	HubActivityPhase,
	HubActivityUpdate,
	HubClientMessage,
	HubCommandResult,
	HubExtensionUIOutbound,
	HubExtensionUIRequest,
	HubPresenceMember,
	HubPresenceUpdate,
	HubQueueUpdate,
	HubRoleGap,
	HubRolePlan,
	HubRoleProgress,
	HubServerMessage,
} from "./protocol.ts";
import { RoleOrchestrator } from "./role-orchestrator.ts";
import { discoverRoles } from "./roles/discovery.ts";
import type { RoomConfigFile, RoomRegistry } from "./room-registry.ts";
import { safeStringify } from "./safe-json.ts";
import { buildSessionState } from "./state-snapshot.ts";

export interface RoomClient {
	id: string;
	displayName: string;
	socket: WebSocket;
}

export interface RoomOptions {
	roomId: string;
	sessionResult: CreateAgentSessionResult;
	cwd: string;
	rolesConfig: ResolvedHubRolesConfig;
	modelsConfig: ResolvedHubModelsConfig;
	roomConfig: RoomConfigFile;
	registry: RoomRegistry;
}

export class Room {
	readonly roomId: string;
	readonly session: AgentSession;
	readonly cwd: string;
	readonly modelsConfig: ResolvedHubModelsConfig;
	private readonly rolesConfig: ResolvedHubRolesConfig;
	private readonly registry: RoomRegistry;
	private roomConfig: RoomConfigFile;
	private roleModelOverrides: Record<string, string>;
	private queueAbortController: AbortController | null = null;
	private readonly clients = new Map<string, RoomClient>();
	private unsubscribeSession: (() => void) | undefined;
	private readonly extensionUi: ExtensionUiRouter;
	private readonly queue: PromptQueue;
	private activityPhase: HubActivityPhase = "idle";
	private activityDetail: string | undefined;
	private activityHostDisplayName: string | null = null;

	constructor(options: RoomOptions) {
		this.roomId = options.roomId;
		this.session = options.sessionResult.session;
		this.cwd = options.cwd;
		this.modelsConfig = options.modelsConfig;
		this.rolesConfig = options.rolesConfig;
		this.registry = options.registry;
		this.roomConfig = options.roomConfig;
		this.roleModelOverrides = { ...options.modelsConfig.roleModels };

		const roleOrchestrator = this.isRolesEnabledForRoom()
			? new RoleOrchestrator({
					session: this.session,
					cwd: options.cwd,
					roomId: options.roomId,
					registry: options.registry,
					rolesConfig: options.rolesConfig,
					getRoomConfig: () => this.roomConfig,
					getRoleModelOverrides: () => this.roleModelOverrides,
					onBroadcast: (msg) => this.broadcastRoleEvent(msg),
				})
			: undefined;

		this.queue = new PromptQueue(
			this.session,
			(update) => {
				this.broadcast(update);
				this.syncActivityFromQueue();
			},
			{
				roleOrchestrator,
				getAbortSignal: () => this.queueAbortController?.signal,
				onTurnStart: () => {
					this.queueAbortController = new AbortController();
				},
				onTurnEnd: () => {
					this.queueAbortController = null;
				},
			},
		);

		this.extensionUi = new ExtensionUiRouter(
			(request, targetClientId) => this.broadcastExtensionUi(request, targetClientId),
			() => this.queue.getTurnOriginClientId(),
		);
	}

	isRolesEnabledForRoom(): boolean {
		if (this.roomConfig.rolesEnabled === true) {
			return true;
		}
		if (this.roomConfig.rolesEnabled === false) {
			return false;
		}
		return this.rolesConfig.enabled;
	}

	reloadRoomConfig(config: RoomConfigFile): void {
		this.roomConfig = config;
	}

	private broadcastRoleEvent(message: HubRolePlan | HubRoleGap | HubRoleProgress): void {
		this.broadcast(message);
	}

	async listCatalogModels() {
		return listHubModels(this.session.modelRegistry, this.modelsConfig.catalog);
	}

	async buildModelsConfigPayload() {
		const models = await this.listCatalogModels();
		const discovery = discoverRoles({
			cwd: this.cwd,
			rolesDir: this.rolesConfig.rolesDir,
		});
		const rolesWithModels = applyRoleModelOverrides(discovery.roles, this.roleModelOverrides);
		return {
			models,
			catalog: this.modelsConfig.catalog,
			sessionModelRef: this.modelsConfig.sessionModelRef,
			roles: buildRoleModelEntries(rolesWithModels, this.roleModelOverrides),
		};
	}

	/** Apply models.session from hub.json, or first catalog model with auth if session is unavailable. */
	async applyConfiguredSessionModel(): Promise<void> {
		const model = await this.resolveSessionModel();
		if (!model) {
			return;
		}
		await this.session.setModel(model);
	}

	private async resolveSessionModel() {
		const available = await this.session.modelRegistry.getAvailable();
		const findRef = (refStr: string | undefined) => {
			const ref = refStr ? parseModelRef(refStr) : undefined;
			if (!ref) {
				return undefined;
			}
			return available.find((m) => m.provider === ref.provider && m.id === ref.modelId);
		};

		const sessionRef = this.modelsConfig.sessionModelRef;
		const sessionModel = findRef(sessionRef);
		if (sessionModel) {
			return sessionModel;
		}

		if (sessionRef) {
			console.warn(`[pi-hub] models.session not available: ${sessionRef}; trying models.catalog fallback`);
		}

		for (const entry of this.modelsConfig.catalog) {
			const model = findRef(entry);
			if (model && this.session.modelRegistry.hasConfiguredAuth(model)) {
				console.log(`[pi-hub] Using catalog session model: ${entry}`);
				return model;
			}
		}

		for (const entry of this.modelsConfig.catalog) {
			const model = findRef(entry);
			if (model) {
				console.warn(`[pi-hub] Using catalog session model without auth: ${entry}`);
				return model;
			}
		}

		return undefined;
	}

	async start(): Promise<void> {
		await this.session.bindExtensions({
			uiContext: this.extensionUi.createContext(),
			onError: (err) => {
				console.error(`[pi-hub] extension error (${err.extensionPath}): ${err.error}`);
			},
		});

		this.unsubscribeSession = this.session.subscribe((event) => {
			this.handleSessionEvent(event);
		});
	}

	async stop(): Promise<void> {
		this.unsubscribeSession?.();
		this.unsubscribeSession = undefined;
		for (const client of this.clients.values()) {
			client.socket.close();
		}
		this.clients.clear();
	}

	addClient(socket: WebSocket, displayName: string): RoomClient {
		const client: RoomClient = {
			id: crypto.randomUUID(),
			displayName: displayName.trim() || "anonymous",
			socket,
		};
		this.clients.set(client.id, client);
		this.broadcastPresence();
		return client;
	}

	removeClient(clientId: string): void {
		if (!this.clients.delete(clientId)) {
			return;
		}
		this.broadcastPresence();
	}

	getClientCount(): number {
		return this.clients.size;
	}

	private getPresenceDisplayNames(): string[] {
		return [...this.clients.values()].map((c) => c.displayName);
	}

	getClient(clientId: string): RoomClient | undefined {
		return this.clients.get(clientId);
	}

	sendJoined(client: RoomClient): void {
		this.send(client, {
			type: "joined",
			clientId: client.id,
			roomId: this.roomId,
			state: buildSessionState(this.session),
			messages: this.session.messages,
		});
		this.send(client, {
			type: "queue_update",
			pending: [],
			current: null,
		});
		this.broadcastPresence();
	}

	async handleMessage(client: RoomClient, message: HubClientMessage): Promise<void> {
		switch (message.type) {
			case "join":
				this.sendError(client, "already_joined", "Send join only before room membership is established");
				return;

			case "prompt": {
				const mentions = resolveMessageMentions(message.message, {
					roleNames: this.roomConfig.roleNames ?? [],
					userNames: this.getPresenceDisplayNames(),
				});
				const result = this.queue.enqueue({
					command: "prompt",
					clientId: client.id,
					displayName: client.displayName,
					message: message.message,
					images: message.images,
					streamingBehavior: message.streamingBehavior,
					mentionedRoles: mentions.roles,
					mentionedUsers: mentions.users,
					id: message.id,
				});
				this.sendCommandResult(client, "prompt", message.id, result.accepted, result.error);
				return;
			}

			case "steer": {
				const result = this.queue.enqueue({
					command: "steer",
					clientId: client.id,
					displayName: client.displayName,
					message: message.message,
					images: message.images,
					id: message.id,
				});
				this.sendCommandResult(client, "steer", message.id, result.accepted, result.error);
				return;
			}

			case "follow_up": {
				const result = this.queue.enqueue({
					command: "follow_up",
					clientId: client.id,
					displayName: client.displayName,
					message: message.message,
					images: message.images,
					id: message.id,
				});
				this.sendCommandResult(client, "follow_up", message.id, result.accepted, result.error);
				return;
			}

			case "abort": {
				try {
					this.queueAbortController?.abort();
					await this.session.abort();
					this.sendCommandResult(client, "abort", message.id, true);
				} catch (err) {
					const msg = err instanceof Error ? err.message : String(err);
					this.sendCommandResult(client, "abort", message.id, false, msg);
				}
				return;
			}

			case "get_state": {
				this.send(client, {
					type: "joined",
					clientId: client.id,
					roomId: this.roomId,
					state: buildSessionState(this.session),
					messages: this.session.messages,
				});
				this.sendCommandResult(client, "get_state", message.id, true);
				return;
			}

			case "get_available_models": {
				try {
					const models = await this.listCatalogModels();
					this.sendCommandResult(client, "get_available_models", message.id, true, undefined, { models });
				} catch (err) {
					const msg = err instanceof Error ? err.message : String(err);
					this.sendCommandResult(client, "get_available_models", message.id, false, msg);
				}
				return;
			}

			case "get_models_config": {
				try {
					const payload = await this.buildModelsConfigPayload();
					this.sendCommandResult(client, "get_models_config", message.id, true, undefined, payload);
				} catch (err) {
					const msg = err instanceof Error ? err.message : String(err);
					this.sendCommandResult(client, "get_models_config", message.id, false, msg);
				}
				return;
			}

			case "set_role_model": {
				try {
					const roleName = message.roleName.trim();
					if (!roleName) {
						this.sendCommandResult(client, "set_role_model", message.id, false, "roleName is required");
						return;
					}
					let modelRef: string | null = null;
					if (message.provider && message.modelId) {
						modelRef = `${message.provider}/${message.modelId}`;
						const catalogModels = await this.listCatalogModels();
						const found = catalogModels.some((m) => m.provider === message.provider && m.id === message.modelId);
						if (!found) {
							this.sendCommandResult(
								client,
								"set_role_model",
								message.id,
								false,
								`Model not in catalog: ${modelRef}`,
							);
							return;
						}
					}
					this.roleModelOverrides = persistRoleModelOverride(this.cwd, roleName, modelRef);
					const payload = await this.buildModelsConfigPayload();
					this.sendCommandResult(client, "set_role_model", message.id, true, undefined, payload);
				} catch (err) {
					const msg = err instanceof Error ? err.message : String(err);
					this.sendCommandResult(client, "set_role_model", message.id, false, msg);
				}
				return;
			}

			case "set_model": {
				try {
					const catalogModels = await this.listCatalogModels();
					const modelInfo = catalogModels.find((m) => m.provider === message.provider && m.id === message.modelId);
					if (!modelInfo) {
						this.sendCommandResult(
							client,
							"set_model",
							message.id,
							false,
							`Model not found in catalog: ${message.provider}/${message.modelId}`,
						);
						return;
					}
					const models = await this.session.modelRegistry.getAvailable();
					const model = models.find((m) => m.provider === message.provider && m.id === message.modelId);
					if (!model) {
						this.sendCommandResult(
							client,
							"set_model",
							message.id,
							false,
							`Model not found: ${message.provider}/${message.modelId}`,
						);
						return;
					}
					await this.session.setModel(model);
					this.broadcastStateUpdate();
					this.sendCommandResult(client, "set_model", message.id, true, undefined, {
						model: buildSessionState(this.session).model,
					});
				} catch (err) {
					const msg = err instanceof Error ? err.message : String(err);
					this.sendCommandResult(client, "set_model", message.id, false, msg);
				}
				return;
			}

			case "set_provider_base_url": {
				try {
					const provider = message.provider.trim();
					const baseUrl = message.baseUrl.trim();
					if (!provider || !baseUrl) {
						this.sendCommandResult(
							client,
							"set_provider_base_url",
							message.id,
							false,
							"provider and baseUrl are required",
						);
						return;
					}
					const available = await this.session.modelRegistry.getAvailable();
					if (!available.some((m) => m.provider === provider)) {
						this.sendCommandResult(
							client,
							"set_provider_base_url",
							message.id,
							false,
							`Unknown provider: ${provider}`,
						);
						return;
					}
					this.session.modelRegistry.registerProvider(provider, { baseUrl });
					const current = this.session.model;
					if (current?.provider === provider) {
						const updated = this.session.modelRegistry.find(provider, current.id);
						if (updated) {
							await this.session.setModel(updated);
						}
					}
					this.broadcastStateUpdate();
					const models = await this.listCatalogModels();
					this.sendCommandResult(client, "set_provider_base_url", message.id, true, undefined, { models });
				} catch (err) {
					const msg = err instanceof Error ? err.message : String(err);
					this.sendCommandResult(client, "set_provider_base_url", message.id, false, msg);
				}
				return;
			}

			case "extension_ui_response": {
				if (!this.extensionUi.handleResponse(message)) {
					this.sendError(client, "unknown_extension_ui", `No pending extension UI request: ${message.id}`);
				}
				return;
			}
		}
	}

	private handleSessionEvent(event: AgentSessionEvent): void {
		try {
			if (event.type === "agent_end") {
				this.queue.notifyAgentIdle();
			}
			this.updateActivityFromEvent(event);
			const hostDisplayName = this.queue.getTurnOriginDisplayName() ?? undefined;
			this.broadcast({ type: "agent_event", event, hostDisplayName });
		} catch (err) {
			const message = err instanceof Error ? err.message : String(err);
			console.error(`[pi-hub] session event error: ${message}`);
		}
	}

	private syncActivityFromQueue(): void {
		if (this.queue.getTurnOriginDisplayName() === null && !this.session.isStreaming && !this.session.isCompacting) {
			this.setActivity("idle");
		}
	}

	private updateActivityFromEvent(event: AgentSessionEvent): void {
		switch (event.type) {
			case "agent_start":
			case "turn_start":
				this.setActivity("replying");
				return;
			case "message_update": {
				const sub = event.assistantMessageEvent?.type;
				if (sub === "thinking_delta") {
					this.setActivity("thinking");
				} else if (sub === "text_delta") {
					this.setActivity("replying");
				}
				return;
			}
			case "tool_execution_start":
				this.setActivity("tool", event.toolName);
				return;
			case "tool_execution_end":
				this.setActivity(this.session.isStreaming ? "replying" : "idle");
				return;
			case "compaction_start":
				this.setActivity("compacting", event.reason);
				return;
			case "compaction_end":
				this.setActivity(this.session.isStreaming ? "replying" : "idle");
				return;
			case "agent_end":
				this.setActivity(this.session.isStreaming ? "replying" : "idle");
				return;
		}
	}

	private setActivity(phase: HubActivityPhase, detail?: string): void {
		const hostDisplayName = this.queue.getTurnOriginDisplayName();
		if (
			this.activityPhase === phase &&
			this.activityDetail === detail &&
			this.activityHostDisplayName === hostDisplayName
		) {
			return;
		}
		this.activityPhase = phase;
		this.activityDetail = detail;
		this.activityHostDisplayName = hostDisplayName;
		const update: HubActivityUpdate = {
			type: "activity_update",
			hostDisplayName,
			phase,
			detail,
		};
		this.broadcast(update);
	}

	private broadcastExtensionUi(request: HubExtensionUIRequest, targetClientId: string | null): void {
		const waitingForDisplayName =
			targetClientId !== null ? (this.clients.get(targetClientId)?.displayName ?? "operator") : undefined;
		const outbound: HubExtensionUIOutbound = {
			...request,
			targetClientId,
			waitingForDisplayName,
		};
		this.broadcast(outbound);
	}

	private broadcastPresence(): void {
		const update: HubPresenceUpdate = {
			type: "presence",
			members: [...this.clients.values()].map(
				(c): HubPresenceMember => ({
					clientId: c.id,
					displayName: c.displayName,
				}),
			),
		};
		this.broadcast(update);
	}

	broadcastRoomDeleted(): void {
		this.broadcast({ type: "room_deleted", roomId: this.roomId });
	}

	broadcast(message: HubServerMessage | HubQueueUpdate | HubRolePlan | HubRoleGap | HubRoleProgress): void {
		const data = safeStringify(message);
		if (!data) {
			return;
		}
		for (const client of this.clients.values()) {
			if (client.socket.readyState === client.socket.OPEN) {
				client.socket.send(data);
			}
		}
	}

	private send(client: RoomClient, message: HubServerMessage | HubQueueUpdate): void {
		if (client.socket.readyState !== client.socket.OPEN) {
			return;
		}
		const data = safeStringify(message);
		if (data) {
			client.socket.send(data);
		}
	}

	private broadcastStateUpdate(): void {
		this.broadcast({ type: "state_update", state: buildSessionState(this.session) });
	}

	private sendCommandResult(
		client: RoomClient,
		command: string,
		id: string | undefined,
		success: boolean,
		error?: string,
		data?: unknown,
	): void {
		const result: HubCommandResult = { type: "command_result", command, id, success, error, data };
		this.send(client, result);
	}

	private sendError(client: RoomClient, code: string, message: string): void {
		this.send(client, { type: "error", code, message });
	}

	/** Send current session state + messages to all clients (used after session clear). */
	sendClientUpdate(): void {
		for (const client of this.clients.values()) {
			this.send(client, {
				type: "joined",
				clientId: client.id,
				roomId: this.roomId,
				state: buildSessionState(this.session),
				messages: [],
			});
		}
	}
}

import type { ImageContent } from "@earendil-works/pi-ai";
import type { AgentSession } from "@earendil-works/pi-coding-agent";
import { formatUserMentionPrefix } from "./mentions.ts";
import type { HubQueueItemSnapshot, HubQueueUpdate } from "./protocol.ts";
import type { RoleOrchestrator } from "./role-orchestrator.ts";

export type QueueCommand = "prompt" | "steer" | "follow_up";

export interface QueueItem {
	id: string;
	command: QueueCommand;
	clientId: string;
	displayName: string;
	message: string;
	images?: ImageContent[];
	streamingBehavior?: "steer" | "followUp";
	/** Room-assigned role names from @mentions; empty means direct session prompt. */
	mentionedRoles?: string[];
	mentionedUsers?: string[];
	queuedAt: string;
}

export type QueueUpdateListener = (update: HubQueueUpdate) => void;

export interface PromptQueueOptions {
	roleOrchestrator?: RoleOrchestrator;
	getAbortSignal?: () => AbortSignal | undefined;
	onTurnStart?: () => void;
	onTurnEnd?: () => void;
}

export class PromptQueue {
	private items: QueueItem[] = [];
	private current: QueueItem | null = null;
	private draining = false;
	private idleWaiters: Array<() => void> = [];
	private turnOriginClientId: string | null = null;
	private readonly session: AgentSession;
	private readonly onUpdate: QueueUpdateListener;
	private readonly roleOrchestrator: RoleOrchestrator | undefined;
	private readonly getAbortSignal: (() => AbortSignal | undefined) | undefined;
	private readonly onTurnStart: (() => void) | undefined;
	private readonly onTurnEnd: (() => void) | undefined;

	constructor(session: AgentSession, onUpdate: QueueUpdateListener, options?: PromptQueueOptions) {
		this.session = session;
		this.onUpdate = onUpdate;
		this.roleOrchestrator = options?.roleOrchestrator;
		this.getAbortSignal = options?.getAbortSignal;
		this.onTurnStart = options?.onTurnStart;
		this.onTurnEnd = options?.onTurnEnd;
	}

	getTurnOriginClientId(): string | null {
		return this.turnOriginClientId;
	}

	getTurnOriginDisplayName(): string | null {
		return this.current?.displayName ?? null;
	}

	enqueue(item: Omit<QueueItem, "id" | "queuedAt"> & { id?: string }): {
		accepted: boolean;
		position: number;
		error?: string;
	} {
		const entry: QueueItem = {
			id: item.id ?? crypto.randomUUID(),
			queuedAt: new Date().toISOString(),
			command: item.command,
			clientId: item.clientId,
			displayName: item.displayName,
			message: item.message,
			images: item.images,
			streamingBehavior: item.streamingBehavior,
			mentionedRoles: item.mentionedRoles,
			mentionedUsers: item.mentionedUsers,
		};

		if (entry.command === "prompt" && this.session.isStreaming && !entry.streamingBehavior) {
			this.items.push(entry);
			this.emitUpdate();
			void this.drain();
			return { accepted: true, position: this.items.length };
		}

		this.items.push(entry);
		this.emitUpdate();
		void this.drain();
		return { accepted: true, position: this.items.length };
	}

	notifyAgentIdle(): void {
		const waiters = this.idleWaiters;
		this.idleWaiters = [];
		for (const resolve of waiters) {
			resolve();
		}
		void this.drain();
	}

	private emitUpdate(): void {
		this.onUpdate({
			type: "queue_update",
			pending: this.items.map(toSnapshot),
			current: this.current ? toSnapshot(this.current) : null,
		});
	}

	private async waitUntilIdle(): Promise<void> {
		if (!this.session.isStreaming) {
			return;
		}
		await new Promise<void>((resolve) => {
			this.idleWaiters.push(resolve);
		});
	}

	private async drain(): Promise<void> {
		if (this.draining) {
			return;
		}
		this.draining = true;
		try {
			while (this.items.length > 0) {
				await this.waitUntilIdle();
				const item = this.items.shift()!;
				this.current = item;
				this.turnOriginClientId = item.clientId;
				this.onTurnStart?.();
				this.emitUpdate();

				try {
					if (item.command === "prompt") {
						await this.runPrompt(item);
					} else if (item.command === "steer") {
						await this.session.steer(item.message, item.images);
					} else {
						await this.session.followUp(item.message, item.images);
					}
					await this.waitUntilIdle();
				} catch (err) {
					const message = err instanceof Error ? err.message : String(err);
					const who = item.displayName ? ` (${item.displayName})` : "";
					const roles =
						item.mentionedRoles && item.mentionedRoles.length > 0
							? ` @roles=${item.mentionedRoles.join(",")}`
							: "";
					console.error(`[pi-hub] queue item failed${who}${roles}: ${message}`);
				} finally {
					this.current = null;
					this.turnOriginClientId = null;
					this.onTurnEnd?.();
					this.emitUpdate();
				}
			}
		} finally {
			this.draining = false;
		}
	}

	private async runPrompt(item: QueueItem): Promise<void> {
		const orchestrator = this.roleOrchestrator;
		const signal = this.getAbortSignal?.();
		const mentionedRoles = item.mentionedRoles ?? [];
		if (mentionedRoles.length > 0 && orchestrator?.isReady()) {
			await orchestrator.run(item.message, signal, {
				mentionedRoles,
				mentionedUsers: item.mentionedUsers,
			});
			return;
		}

		const userPrefix = formatUserMentionPrefix(item.mentionedUsers ?? []);
		const message = userPrefix ? `${userPrefix}${item.message}` : item.message;
		await this.session.prompt(message, {
			images: item.images,
			streamingBehavior: item.streamingBehavior,
			source: "rpc",
		});
	}
}

function toSnapshot(item: QueueItem): HubQueueItemSnapshot {
	return {
		id: item.id,
		clientId: item.clientId,
		displayName: item.displayName,
		command: item.command,
		queuedAt: item.queuedAt,
	};
}

import type { WebSocket } from "ws";
import type { ResolvedHubRolesConfig } from "./config.ts";
import type { HubCommandResult, HubRoomConfigPayload, HubScopedClientMessage } from "./protocol.ts";
import {
	deleteRoleFile,
	getRoleContent,
	listRoleSummaries,
	RoleStoreError,
	saveRoleContent,
} from "./roles/role-store.ts";
import { getSkillContent, listSkillFiles } from "./roles/skill-store.ts";
import type { RoomManager } from "./room-manager.ts";
import { RoomRegistryError } from "./room-registry.ts";
import {
	addRoomRoleName,
	assertRolesExist,
	normalizeRoleNames,
	removeRoomRoleName,
	type ValidateRoomRolesOptions,
} from "./room-roles.ts";

export interface HubAdminOptions {
	token: string;
	roomManager: RoomManager;
	rolesConfig: ResolvedHubRolesConfig;
	cwd: string;
}

export class HubAdmin {
	private readonly options: HubAdminOptions;

	constructor(options: HubAdminOptions) {
		this.options = options;
	}

	private roleValidateOptions(): ValidateRoomRolesOptions {
		return { cwd: this.options.cwd, rolesDir: this.options.rolesConfig.rolesDir };
	}

	private reloadActiveRoomConfig(roomId: string, config: ReturnType<RoomManager["registry"]["loadRoomConfig"]>): void {
		const active = this.options.roomManager.getActiveRoom(roomId);
		if (active) {
			active.reloadRoomConfig(config);
		}
	}

	async handle(ws: WebSocket, message: HubScopedClientMessage): Promise<void> {
		if (!this.checkToken(message.token)) {
			this.send(ws, { type: "error", code: "unauthorized", message: "Invalid token" });
			return;
		}

		try {
			switch (message.type) {
				case "list_rooms":
					await this.handleListRooms(ws, message.id);
					return;
				case "create_room":
					await this.handleCreateRoom(ws, message.roomId, message.title, message.id);
					return;
				case "delete_room":
					await this.handleDeleteRoom(ws, message.roomId, message.deleteFiles, message.id);
					return;
				case "get_room_config":
					await this.handleGetRoomConfig(ws, message.roomId, message.id);
					return;
				case "set_room_config":
					await this.handleSetRoomConfig(ws, message.roomId, message.config, message.id);
					return;
				case "add_room_role":
					await this.handleAddRoomRole(ws, message.roomId, message.roleName, message.id);
					return;
				case "remove_room_role":
					await this.handleRemoveRoomRole(ws, message.roomId, message.roleName, message.id);
					return;
				case "set_room_roles":
					await this.handleSetRoomRoles(ws, message.roomId, message.roleNames, message.id);
					return;
				case "list_roles":
					await this.handleListRoles(ws, message.id);
					return;
				case "get_role":
					await this.handleGetRole(ws, message.name, message.id);
					return;
				case "save_role":
					await this.handleSaveRole(ws, message.name, message.content, message.id);
					return;
				case "delete_role":
					await this.handleDeleteRole(ws, message.name, message.id);
					return;
				case "list_skills":
					await this.handleListSkills(ws, message.id);
					return;
				case "get_skill_content":
					await this.handleGetSkillContent(ws, message.name, message.id);
					return;
				case "clear_room_session":
					await this.handleClearRoomSession(ws, message.roomId, message.id);
					return;
			}
		} catch (err) {
			const msg = err instanceof Error ? err.message : String(err);
			const code =
				err instanceof RoomRegistryError ? err.code : err instanceof RoleStoreError ? err.code : "internal";
			this.sendCommandResult(ws, message.type, message.id, false, msg, undefined);
			if (message.type !== "list_rooms") {
				this.send(ws, { type: "error", code, message: msg });
			}
		}
	}

	private checkToken(clientToken: string): boolean {
		return clientToken.trim() === this.options.token.trim();
	}

	private async handleListRooms(ws: WebSocket, id?: string): Promise<void> {
		const entries = this.options.roomManager.listRooms();
		const rooms = entries.map((e) => ({
			roomId: e.roomId,
			title: e.title,
			createdAt: e.createdAt,
			updatedAt: e.updatedAt,
			clientCount: this.options.roomManager.getActiveRoom(e.roomId)?.getClientCount() ?? 0,
		}));
		this.send(ws, { type: "rooms_list", rooms });
		this.sendCommandResult(ws, "list_rooms", id, true, undefined, { rooms });
	}

	private async handleCreateRoom(
		ws: WebSocket,
		roomId: string,
		title: string | undefined,
		id?: string,
	): Promise<void> {
		const entry = this.options.roomManager.createRoom(roomId, title);
		const rooms = this.options.roomManager.listRooms().map((e) => ({
			roomId: e.roomId,
			title: e.title,
			createdAt: e.createdAt,
			updatedAt: e.updatedAt,
			clientCount: 0,
		}));
		this.send(ws, { type: "rooms_list", rooms });
		this.sendCommandResult(ws, "create_room", id, true, undefined, { room: entry });
	}

	private async handleDeleteRoom(
		ws: WebSocket,
		roomId: string,
		deleteFiles: boolean | undefined,
		id?: string,
	): Promise<void> {
		const active = this.options.roomManager.getActiveRoom(roomId);
		if (active) {
			active.broadcastRoomDeleted();
		}
		await this.options.roomManager.deleteRoom(roomId, { deleteFiles: deleteFiles !== false });
		this.send(ws, { type: "room_deleted", roomId });
		const rooms = this.options.roomManager.listRooms().map((e) => ({
			roomId: e.roomId,
			title: e.title,
			createdAt: e.createdAt,
			updatedAt: e.updatedAt,
			clientCount: 0,
		}));
		this.send(ws, { type: "rooms_list", rooms });
		this.sendCommandResult(ws, "delete_room", id, true);
	}

	private handleGetRoomConfig(ws: WebSocket, roomId: string, id?: string): void {
		const config = this.options.roomManager.registry.loadRoomConfig(roomId);
		this.sendCommandResult(ws, "get_room_config", id, true, undefined, { config });
	}

	private handleSetRoomConfig(ws: WebSocket, roomId: string, config: HubRoomConfigPayload, id?: string): void {
		const saved = this.options.roomManager.registry.saveRoomConfig(roomId, config, this.roleValidateOptions());
		this.reloadActiveRoomConfig(roomId, saved);
		this.sendCommandResult(ws, "set_room_config", id, true, undefined, { config: saved });
	}

	private handleAddRoomRole(ws: WebSocket, roomId: string, roleName: string, id?: string): void {
		const validateOpts = this.roleValidateOptions();
		const name = roleName.trim();
		assertRolesExist([name], validateOpts);
		const current = this.options.roomManager.registry.loadRoomConfig(roomId);
		const roleNames = addRoomRoleName(current.roleNames, name);
		const saved = this.options.roomManager.registry.saveRoomConfig(roomId, { roleNames }, validateOpts);
		this.reloadActiveRoomConfig(roomId, saved);
		this.sendCommandResult(ws, "add_room_role", id, true, undefined, { config: saved });
	}

	private handleRemoveRoomRole(ws: WebSocket, roomId: string, roleName: string, id?: string): void {
		const validateOpts = this.roleValidateOptions();
		const current = this.options.roomManager.registry.loadRoomConfig(roomId);
		const roleNames = removeRoomRoleName(current.roleNames, roleName);
		const saved = this.options.roomManager.registry.saveRoomConfig(roomId, { roleNames }, validateOpts);
		this.reloadActiveRoomConfig(roomId, saved);
		this.sendCommandResult(ws, "remove_room_role", id, true, undefined, { config: saved });
	}

	private handleSetRoomRoles(ws: WebSocket, roomId: string, roleNames: string[], id?: string): void {
		const validateOpts = this.roleValidateOptions();
		const normalized = normalizeRoleNames(roleNames);
		assertRolesExist(normalized, validateOpts);
		const saved = this.options.roomManager.registry.saveRoomConfig(roomId, { roleNames: normalized }, validateOpts);
		this.reloadActiveRoomConfig(roomId, saved);
		this.sendCommandResult(ws, "set_room_roles", id, true, undefined, { config: saved });
	}

	private handleListRoles(ws: WebSocket, id?: string): void {
		const roles = listRoleSummaries(this.options.cwd, this.options.rolesConfig.rolesDir);
		this.sendCommandResult(ws, "list_roles", id, true, undefined, { roles });
	}

	private handleGetRole(ws: WebSocket, name: string, id?: string): void {
		const role = getRoleContent(this.options.cwd, this.options.rolesConfig.rolesDir, name);
		this.sendCommandResult(ws, "get_role", id, true, undefined, role);
	}

	private handleSaveRole(ws: WebSocket, name: string, content: string, id?: string): void {
		const role = saveRoleContent(this.options.cwd, this.options.rolesConfig.rolesDir, name, content);
		this.sendCommandResult(ws, "save_role", id, true, undefined, role);
	}

	private handleDeleteRole(ws: WebSocket, name: string, id?: string): void {
		deleteRoleFile(this.options.cwd, this.options.rolesConfig.rolesDir, name, {
			pmRole: this.options.rolesConfig.pmRole,
		});
		this.sendCommandResult(ws, "delete_role", id, true);
	}

	private handleListSkills(ws: WebSocket, id?: string): void {
		const skills = listSkillFiles({ cwd: this.options.cwd });
		this.sendCommandResult(ws, "list_skills", id, true, undefined, { skills });
	}

	private handleGetSkillContent(ws: WebSocket, name: string, id?: string): void {
		const skill = getSkillContent(this.options.cwd, name);
		if (!skill) {
			this.sendCommandResult(ws, "get_skill_content", id, false, `Skill "${name}" not found`);
			return;
		}
		this.sendCommandResult(ws, "get_skill_content", id, true, undefined, skill);
	}

	private handleClearRoomSession(ws: WebSocket, roomId: string, id?: string): void {
		const room = this.options.roomManager.getActiveRoom(roomId);
		if (!room) {
			this.sendCommandResult(ws, "clear_room_session", id, false, `Room "${roomId}" not active`);
			return;
		}
		// Clear messages and reset session state
		room.session.agent.reset();
		room.session.sessionManager.newSession();
		// Notify all clients in the room with empty messages
		room.sendClientUpdate();
		this.sendCommandResult(ws, "clear_room_session", id, true);
	}

	private send(ws: WebSocket, message: object): void {
		if (ws.readyState === ws.OPEN) {
			ws.send(JSON.stringify(message));
		}
	}

	private sendCommandResult(
		ws: WebSocket,
		command: string,
		id: string | undefined,
		success: boolean,
		error?: string,
		data?: unknown,
	): void {
		const result: HubCommandResult = { type: "command_result", command, id, success, error, data };
		this.send(ws, result);
	}
}

import type { AgentSession } from "@earendil-works/pi-coding-agent";
import { getAgentDir } from "@earendil-works/pi-coding-agent";
import type { ResolvedHubRolesConfig } from "./config.ts";
import { formatUserMentionPrefix } from "./mentions.ts";
import { applyRoleModelOverrides } from "./models-config.ts";
import { discoverRoles, formatRoomRosterForPm, getRoleByName } from "./roles/discovery.ts";
import { parseTaskPlan } from "./roles/parse-plan.ts";
import { type ResolvedRoleConfig, resolveRoleForRoom } from "./roles/resolve-config.ts";
import { buildRoomContextPrefix } from "./roles/room-context.ts";
import { runRoleSubprocess } from "./roles/runner.ts";
import { planExecutionBatches } from "./roles/topo.ts";
import type {
	RoleGapEvent,
	RolePlanEvent,
	RoleProgressEvent,
	RoleTaskResult,
	TaskPlan,
	TaskPlanGap,
} from "./roles/types.ts";
import type { RoomConfigFile, RoomRegistry } from "./room-registry.ts";

export type RoleOrchestratorBroadcast = (message: RolePlanEvent | RoleGapEvent | RoleProgressEvent) => void;

export interface RoleOrchestratorRunOptions {
	/** Role names from @mentions in the user message (room-assigned only). */
	mentionedRoles: string[];
	mentionedUsers?: string[];
}

export interface RoleOrchestratorOptions {
	session: AgentSession;
	cwd: string;
	roomId: string;
	registry: RoomRegistry;
	rolesConfig: ResolvedHubRolesConfig;
	getRoomConfig: () => RoomConfigFile;
	onBroadcast: RoleOrchestratorBroadcast;
	agentDir?: string;
	getRoleModelOverrides: () => Record<string, string>;
	runRole?: typeof runRoleSubprocess;
}

async function mapWithConcurrencyLimit<TIn, TOut>(
	items: TIn[],
	concurrency: number,
	fn: (item: TIn, index: number) => Promise<TOut>,
): Promise<TOut[]> {
	if (items.length === 0) {
		return [];
	}
	const limit = Math.max(1, Math.min(concurrency, items.length));
	const results: TOut[] = new Array(items.length);
	let nextIndex = 0;
	const workers = new Array(limit).fill(null).map(async () => {
		while (true) {
			const current = nextIndex++;
			if (current >= items.length) {
				return;
			}
			results[current] = await fn(items[current], current);
		}
	});
	await Promise.all(workers);
	return results;
}

function buildPmPrompt(userMessage: string, roomRoster: string, pmRoleName: string): string {
	return `You are the coordinator role "${pmRoleName}" for this room only.

You do NOT have access to a global role library. The roster below is the complete list of worker roles currently assigned to THIS room. Assign tasks only to those role names using each entry's Who / Can do / When to decide fit.

User request:
${userMessage}

Room worker roster (assign tasks only to these roles):
${roomRoster}

Respond with a single JSON object only (no markdown fences), matching this schema:
{"summary":"...","tasks":[{"role":"roleName","task":"...","dependsOn":["otherRole"]}],"uncovered":[{"description":"...","reason":"..."}]}

Rules:
- Only assign to role names listed in the room roster above (not "${pmRoleName}" unless you are also listed as a worker).
- Match tasks to each role's Can do and When to assign; do not assign work a role cannot or should not handle.
- Put work no roster role can handle in uncovered with a clear reason.
- Use dependsOn only when a task needs another role's output first.`;
}

function buildSynthesisPrompt(userMessage: string, plan: TaskPlan, results: RoleTaskResult[]): string {
	const sections = results.map((r) => {
		const status = r.exitCode === 0 ? "completed" : "failed";
		return `### Role: ${r.role} (${status})\nTask: ${r.task}\n\n${r.output}`;
	});
	return `[Orchestrated multi-role run — respond to the user in one cohesive assistant message.]\n\nOriginal user request:\n${userMessage}\n\nPM summary: ${plan.summary}\n\nRole outputs:\n\n${sections.join("\n\n---\n\n")}`;
}

function combineContextPrefix(...parts: (string | undefined)[]): string | undefined {
	const merged = parts.filter((p) => p && p.trim().length > 0) as string[];
	return merged.length > 0 ? merged.join("\n\n") : undefined;
}

export class RoleOrchestrator {
	private readonly session: AgentSession;
	private readonly cwd: string;
	private readonly roomId: string;
	private readonly registry: RoomRegistry;
	private readonly rolesConfig: ResolvedHubRolesConfig;
	private readonly getRoomConfig: () => RoomConfigFile;
	private readonly onBroadcast: RoleOrchestratorBroadcast;
	private readonly agentDir: string;
	private readonly getRoleModelOverrides: () => Record<string, string>;
	private readonly runRole: typeof runRoleSubprocess;

	constructor(options: RoleOrchestratorOptions) {
		this.session = options.session;
		this.cwd = options.cwd;
		this.roomId = options.roomId;
		this.registry = options.registry;
		this.rolesConfig = options.rolesConfig;
		this.getRoomConfig = options.getRoomConfig;
		this.onBroadcast = options.onBroadcast;
		this.agentDir = options.agentDir ?? getAgentDir();
		this.getRoleModelOverrides = options.getRoleModelOverrides;
		this.runRole = options.runRole ?? runRoleSubprocess;
	}

	private roomSkillsDir(): string {
		return this.registry.getRoomSkillsDir(this.roomId);
	}

	private discoverConfiguredRoles(): { roles: ResolvedRoleConfig[] } {
		const roomConfig = this.getRoomConfig();
		const assigned = roomConfig.roleNames ?? [];
		if (assigned.length === 0) {
			return { roles: [] };
		}
		const assignedSet = new Set(assigned);
		const discovery = discoverRoles({
			cwd: this.cwd,
			rolesDir: this.rolesConfig.rolesDir,
			agentDir: this.agentDir,
		});
		const filtered = discovery.roles.filter((r) => assignedSet.has(r.name));
		const withModels = applyRoleModelOverrides(filtered, this.getRoleModelOverrides());
		return {
			roles: withModels.map((r) => resolveRoleForRoom(r, roomConfig, this.cwd)),
		};
	}

	isReady(): boolean {
		const roomConfig = this.getRoomConfig();
		const assigned = roomConfig.roleNames ?? [];
		if (assigned.length === 0) {
			return false;
		}
		const discovery = this.discoverConfiguredRoles();
		const pmRoleName = this.rolesConfig.pmRole;
		const hasWorker = discovery.roles.some((r) => r.name !== pmRoleName);
		return discovery.roles.length > 0 && hasWorker;
	}

	private async recordRoleMessage(
		customType: string,
		content: string,
		details?: Record<string, unknown>,
	): Promise<void> {
		await this.session.sendCustomMessage(
			{
				customType,
				content,
				display: true,
				details,
			},
			{ triggerTurn: false },
		);
	}

	private persistUserMessage(text: string): void {
		this.session.sessionManager.appendMessage({
			role: "user",
			content: [{ type: "text", text }],
			timestamp: Date.now(),
		});
		const sessionContext = this.session.sessionManager.buildSessionContext();
		this.session.agent.state.messages = sessionContext.messages;
	}

	async run(userMessage: string, signal?: AbortSignal, options?: RoleOrchestratorRunOptions): Promise<void> {
		const mentionedRoles = options?.mentionedRoles ?? [];
		const userPrefix = formatUserMentionPrefix(options?.mentionedUsers ?? []);
		const persistedText = userPrefix ? `${userPrefix}${userMessage}` : userMessage;
		this.persistUserMessage(persistedText);

		const discovery = this.discoverConfiguredRoles();
		const roomContext = buildRoomContextPrefix(this.session);

		const mentionedSet = new Set(mentionedRoles);
		const pmRoleName = this.rolesConfig.pmRole;
		const pmRole = getRoleByName(discovery.roles, pmRoleName);
		const allWorkerRoles = discovery.roles.filter((r) => r.name !== pmRoleName);
		const mentionedWorkers = allWorkerRoles.filter((r) => mentionedSet.has(r.name));
		const invokePm = mentionedSet.has(pmRoleName) && pmRole !== undefined;

		if (invokePm && pmRole) {
			// === PM mode: PM plans, workers execute (roster scoped to @mentioned workers when any) ===
			const rosterWorkers = mentionedWorkers.length > 0 ? mentionedWorkers : allWorkerRoles;
			const roomRoster = formatRoomRosterForPm(rosterWorkers);
			const allowedWorkers = new Set(rosterWorkers.map((r) => r.name));

			const pmResult = await this.runRole({
				role: pmRole,
				task: buildPmPrompt(userMessage, roomRoster, this.rolesConfig.pmRole),
				cwd: this.cwd,
				agentDir: this.agentDir,
				contextPrefix: roomContext,
				signal,
				roomSkillsDir: this.roomSkillsDir(),
			});

			if (pmResult.exitCode !== 0) {
				const detail = pmResult.errorMessage ?? pmResult.stderr ?? pmResult.output;
				throw new Error(`PM subprocess failed (exit ${pmResult.exitCode}): ${detail}`);
			}

			const plan = parseTaskPlan(pmResult.output);
			this.onBroadcast({ type: "role_plan", plan });

			const planSummary = `PM plan: ${plan.summary}\nTasks: ${plan.tasks.map((t) => `${t.role}: ${t.task}`).join("; ")}`;
			await this.recordRoleMessage("hub_role_plan", planSummary, { plan });

			const allGaps: TaskPlanGap[] = [...plan.uncovered];
			const roleMap = new Map(rosterWorkers.map((r) => [r.name, r]));

			const executableTasks = [];
			for (const task of plan.tasks) {
				if (task.role === pmRoleName) continue;
				if (!roleMap.has(task.role)) {
					allGaps.push({ description: task.task, reason: `No role named "${task.role}"` });
					continue;
				}
				if (!allowedWorkers.has(task.role)) {
					allGaps.push({
						description: task.task,
						reason: `Role "${task.role}" was not @mentioned in the request`,
					});
					continue;
				}
				executableTasks.push(task);
			}

			if (allGaps.length > 0) {
				this.onBroadcast({ type: "role_gap", uncovered: allGaps });
			}

			const batches = planExecutionBatches(executableTasks);
			const results: RoleTaskResult[] = [];
			const outputsByRole = new Map<string, string>();

			for (const batch of batches) {
				const batchResults = await mapWithConcurrencyLimit(
					batch.tasks,
					this.rolesConfig.maxParallel,
					async (task) => {
						const taskId = crypto.randomUUID();
						const role = roleMap.get(task.role)!;

						this.onBroadcast({ type: "role_progress", role: task.role, taskId, phase: "started" });

						const contextParts: string[] = [];
						if (roomContext) contextParts.push(roomContext);
						for (const dep of task.dependsOn ?? []) {
							const prior = outputsByRole.get(dep);
							if (prior) contextParts.push(`Output from role "${dep}":\n${prior}`);
						}
						const contextPrefix = combineContextPrefix(...contextParts);

						const runResult = await this.runRole({
							role,
							task: task.task,
							cwd: this.cwd,
							agentDir: this.agentDir,
							contextPrefix,
							signal,
							roomSkillsDir: this.roomSkillsDir(),
						});

						const failed = runResult.exitCode !== 0;
						const preview =
							runResult.output.length > 200 ? `${runResult.output.slice(0, 200)}...` : runResult.output;

						this.onBroadcast({
							type: "role_progress",
							role: task.role,
							taskId,
							phase: failed ? "failed" : "done",
							preview,
							fullOutput: runResult.output,
						});

						const statusLabel = failed ? "failed" : "completed";
						await this.recordRoleMessage(
							"hub_role_output",
							`[${role.name}] (${statusLabel})\nTask: ${task.task}\n\n${runResult.output}`,
							{ role: role.name, taskId, task: task.task, exitCode: runResult.exitCode },
						);

						if (!failed) outputsByRole.set(task.role, runResult.output);

						return {
							role: task.role,
							task: task.task,
							taskId,
							exitCode: runResult.exitCode,
							output: runResult.output,
							errorMessage: runResult.errorMessage,
						} satisfies RoleTaskResult;
					},
				);
				results.push(...batchResults);
			}

			const synthesisMessage = buildSynthesisPrompt(persistedText, plan, results);
			await this.session.prompt(synthesisMessage, { source: "rpc" });
		} else if (mentionedWorkers.length > 0) {
			// === Direct mode: each @mentioned worker role runs independently ===
			const results: RoleTaskResult[] = [];

			for (const role of mentionedWorkers) {
				const taskId = crypto.randomUUID();

				this.onBroadcast({ type: "role_progress", role: role.name, taskId, phase: "started" });

				const runResult = await this.runRole({
					role,
					task: userMessage,
					cwd: this.cwd,
					agentDir: this.agentDir,
					contextPrefix: roomContext,
					signal,
					roomSkillsDir: this.roomSkillsDir(),
				});

				const failed = runResult.exitCode !== 0;
				const preview = runResult.output.length > 200 ? `${runResult.output.slice(0, 200)}...` : runResult.output;

				this.onBroadcast({
					type: "role_progress",
					role: role.name,
					taskId,
					phase: failed ? "failed" : "done",
					preview,
					fullOutput: runResult.output,
				});

				const statusLabel = failed ? "failed" : "completed";
				await this.recordRoleMessage("hub_role_output", `[${role.name}] (${statusLabel})\n\n${runResult.output}`, {
					role: role.name,
					taskId,
					exitCode: runResult.exitCode,
				});

				results.push({
					role: role.name,
					task: userMessage,
					taskId,
					exitCode: runResult.exitCode,
					output: runResult.output,
					errorMessage: runResult.errorMessage,
				} satisfies RoleTaskResult);
			}

			if (results.length === 1) {
				const r = results[0]!;
				if (r.exitCode === 0) {
					await this.session.prompt(r.output, { source: "rpc" });
				}
			} else {
				const sections = results.map(
					(r) => `### Role: ${r.role} (${r.exitCode === 0 ? "completed" : "failed"})\n\n${r.output}`,
				);
				const combined = `[Multi-role direct responses]\n\nOriginal request:\n${persistedText}\n\n${sections.join("\n\n---\n\n")}`;
				await this.session.prompt(combined, { source: "rpc" });
			}
		}
	}
}

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join, resolve } from "node:path";

/** Model catalog and per-role/session defaults in hub.json. */
export interface HubModelsConfigFile {
	/** Models shown in Web UI dropdowns (`provider/modelId`). Empty = all registry models with auth. */
	catalog?: string[];
	/** Main session (synthesis) model ref. */
	session?: string;
	/** Per-role subprocess model refs. */
	roleModels?: Record<string, string>;
}

/** Multi-role orchestration settings in hub.json. */
export interface HubRolesConfigFile {
	enabled?: boolean;
	rolesDir?: string;
	pmRole?: string;
	maxParallel?: number;
	confirmProjectRoles?: boolean;
}

/** User-editable hub settings (JSON files). */
export interface HubConfigFile {
	token?: string;
	port?: number;
	host?: string;
	cwd?: string;
	session?: string;
	defaultRoomId?: string;
	/** Override static web root (normally set by CLI/build). */
	publicDir?: string;
	models?: HubModelsConfigFile;
	roles?: HubRolesConfigFile;
}

export type HubTokenSource = "env" | "cli" | "config";

export interface ResolvedHubModelsConfig {
	catalog: string[];
	sessionModelRef?: string;
	roleModels: Record<string, string>;
}

export interface ResolvedHubRolesConfig {
	enabled: boolean;
	rolesDir: string;
	pmRole: string;
	maxParallel: number;
	confirmProjectRoles: boolean;
}

export interface ResolvedHubConfig {
	token?: string;
	/** Where the active token came from (for startup logs). */
	tokenSource?: HubTokenSource;
	port: number;
	host: string;
	cwd: string;
	session?: string;
	defaultRoomId: string;
	publicDir?: string;
	models: ResolvedHubModelsConfig;
	roles: ResolvedHubRolesConfig;
	configPaths: string[];
}

export function normalizeHubToken(token: string | undefined): string | undefined {
	if (token === undefined) return undefined;
	const trimmed = token.trim();
	return trimmed.length > 0 ? trimmed : undefined;
}

const DEFAULT_PORT = 3141;
const DEFAULT_HOST = "0.0.0.0";
const DEFAULT_ROOM_ID = "default";
const DEFAULT_ROLES_DIR = ".pi/roles";
const DEFAULT_PM_ROLE = "pm";
const DEFAULT_MAX_PARALLEL = 4;

export function resolveModelsConfig(file?: HubModelsConfigFile): ResolvedHubModelsConfig {
	const catalog = (file?.catalog ?? []).map((e) => e.trim()).filter((e) => e.length > 0);
	const sessionModelRef = file?.session?.trim() || undefined;
	const roleModels: Record<string, string> = {};
	if (file?.roleModels) {
		for (const [name, ref] of Object.entries(file.roleModels)) {
			const trimmed = ref.trim();
			if (trimmed.length > 0) {
				roleModels[name] = trimmed;
			}
		}
	}
	return { catalog, sessionModelRef, roleModels };
}

export function resolveRolesConfig(file?: HubRolesConfigFile): ResolvedHubRolesConfig {
	return {
		enabled: file?.enabled === true,
		rolesDir: file?.rolesDir ?? DEFAULT_ROLES_DIR,
		pmRole: file?.pmRole ?? DEFAULT_PM_ROLE,
		maxParallel: file?.maxParallel ?? DEFAULT_MAX_PARALLEL,
		confirmProjectRoles: file?.confirmProjectRoles !== false,
	};
}

export function globalConfigPath(): string {
	return join(homedir(), ".pi", "hub.json");
}

export function projectConfigPath(cwd: string): string {
	return join(resolve(cwd), ".pi", "hub.json");
}

export function loadConfigFile(path: string): HubConfigFile {
	if (!existsSync(path)) {
		return {};
	}
	try {
		const raw = readFileSync(path, "utf8");
		const parsed = JSON.parse(raw) as HubConfigFile;
		if (typeof parsed.token === "string") {
			parsed.token = parsed.token.trim();
		}
		return parsed;
	} catch (err) {
		const message = err instanceof Error ? err.message : String(err);
		throw new Error(`Failed to parse ${path}: ${message}`);
	}
}

function mergeConfig(base: HubConfigFile, next: HubConfigFile): HubConfigFile {
	return {
		...base,
		...next,
	};
}

function envString(name: string): string | undefined {
	const value = process.env[name];
	return value && value.length > 0 ? value : undefined;
}

function envNumber(name: string): number | undefined {
	const raw = envString(name);
	if (raw === undefined) return undefined;
	const n = Number(raw);
	return Number.isFinite(n) ? n : undefined;
}

export interface CliOverrides {
	configPath?: string;
	token?: string;
	port?: number;
	host?: string;
	cwd?: string;
	session?: string;
	defaultRoomId?: string;
	publicDir?: string;
}

/** Merge config files, then CLI flags, then environment variables. */
export function resolveHubConfig(overrides: CliOverrides, initialCwd: string): ResolvedHubConfig {
	const configPaths: string[] = [];
	let merged: HubConfigFile = {};

	const globalPath = globalConfigPath();
	if (existsSync(globalPath)) {
		merged = mergeConfig(merged, loadConfigFile(globalPath));
		configPaths.push(globalPath);
	}

	const projectPath = projectConfigPath(initialCwd);
	if (existsSync(projectPath)) {
		merged = mergeConfig(merged, loadConfigFile(projectPath));
		configPaths.push(projectPath);
	}

	if (overrides.configPath) {
		const explicit = resolve(overrides.configPath);
		merged = mergeConfig(merged, loadConfigFile(explicit));
		configPaths.push(explicit);
	} else {
		const envConfig = envString("PI_HUB_CONFIG");
		if (envConfig) {
			const explicit = resolve(envConfig);
			merged = mergeConfig(merged, loadConfigFile(explicit));
			configPaths.push(explicit);
		}
	}

	let token = merged.token;
	let port = merged.port ?? DEFAULT_PORT;
	let host = merged.host ?? DEFAULT_HOST;
	let cwd = merged.cwd ?? initialCwd;
	let session = merged.session;
	let defaultRoomId = merged.defaultRoomId ?? DEFAULT_ROOM_ID;
	let publicDir = merged.publicDir;

	let tokenSource: HubTokenSource | undefined = token !== undefined ? "config" : undefined;

	if (overrides.token !== undefined) {
		token = overrides.token;
		tokenSource = "cli";
	}
	if (overrides.port !== undefined) port = overrides.port;
	if (overrides.host !== undefined) host = overrides.host;
	if (overrides.cwd !== undefined) cwd = overrides.cwd;
	if (overrides.session !== undefined) session = overrides.session;
	if (overrides.defaultRoomId !== undefined) defaultRoomId = overrides.defaultRoomId;
	if (overrides.publicDir !== undefined) publicDir = overrides.publicDir;

	const envToken = envString("PI_HUB_TOKEN");
	if (envToken !== undefined) {
		token = envToken;
		tokenSource = "env";
	}
	port = envNumber("PI_HUB_PORT") ?? port;
	host = envString("PI_HUB_HOST") ?? host;
	cwd = envString("PI_HUB_CWD") ?? cwd;
	session = envString("PI_HUB_SESSION") ?? session;
	defaultRoomId = envString("PI_HUB_DEFAULT_ROOM") ?? defaultRoomId;

	return {
		token: normalizeHubToken(token),
		tokenSource,
		port,
		host,
		cwd: resolve(cwd),
		session,
		defaultRoomId,
		publicDir: publicDir ? resolve(publicDir) : undefined,
		models: resolveModelsConfig(merged.models),
		roles: resolveRolesConfig(merged.roles),
		configPaths,
	};
}

export interface WriteConfigOptions {
	global: boolean;
	cwd: string;
	overwrite: boolean;
}

export function writeExampleConfig(options: WriteConfigOptions): string {
	const path = options.global ? globalConfigPath() : projectConfigPath(options.cwd);
	if (existsSync(path) && !options.overwrite) {
		throw new Error(`Config already exists: ${path} (use --force to overwrite)`);
	}

	const dir = dirname(path);
	if (!existsSync(dir)) {
		mkdirSync(dir, { recursive: true });
	}

	const token = generateToken();
	const example: HubConfigFile = {
		token,
		port: DEFAULT_PORT,
		host: DEFAULT_HOST,
		cwd: options.global ? undefined : options.cwd,
		defaultRoomId: DEFAULT_ROOM_ID,
	};

	writeFileSync(path, `${JSON.stringify(example, null, 2)}\n`, "utf8");
	return path;
}

export function generateToken(): string {
	const bytes = new Uint8Array(24);
	crypto.getRandomValues(bytes);
	return Buffer.from(bytes).toString("base64url");
}

export function formatConfigHelp(): string {
	return `Configuration (later sources override earlier):

  Files (merged in order):
    1. ${globalConfigPath()}
    2. <cwd>/.pi/hub.json
    3. --config <path>  or  PI_HUB_CONFIG

  Environment:
    PI_HUB_TOKEN, PI_HUB_PORT, PI_HUB_HOST, PI_HUB_CWD,
    PI_HUB_SESSION, PI_HUB_DEFAULT_ROOM, PI_HUB_CONFIG

  CLI flags override files and env for the same field.

  Create a starter file:
    pi-hub init              -> .pi/hub.json in current directory
    pi-hub init --global     -> ~/.pi/hub.json
`;
}

import { type Dirent, existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import { getAgentDir, parseFrontmatter } from "@earendil-works/pi-coding-agent";
import type { RoleConfig } from "./types.ts";

export interface DiscoverRolesOptions {
	cwd: string;
	rolesDir: string;
	agentDir?: string;
}

export interface DiscoverRolesResult {
	roles: RoleConfig[];
	projectRolesDir: string | null;
	userRolesDir: string;
}

function loadRolesFromDir(dir: string, source: "user" | "project", cwd: string): RoleConfig[] {
	const roles: RoleConfig[] = [];
	if (!existsSync(dir)) {
		return roles;
	}

	let entries: Dirent[];
	try {
		entries = readdirSync(dir, { withFileTypes: true });
	} catch {
		return roles;
	}

	for (const entry of entries) {
		if (!entry.name.endsWith(".md")) continue;
		if (!entry.isFile() && !entry.isSymbolicLink()) continue;

		const filePath = join(dir, entry.name);
		let content: string;
		try {
			content = readFileSync(filePath, "utf-8");
		} catch {
			continue;
		}

		const { frontmatter, body } = parseFrontmatter<Record<string, string>>(content);
		if (!frontmatter.name || !frontmatter.description) {
			continue;
		}

		const tools = frontmatter.tools
			?.split(",")
			.map((t) => t.trim())
			.filter(Boolean);

		const skills = frontmatter.skills
			?.split(",")
			.map((s) => s.trim())
			.filter(Boolean);

		let rulesPath: string | undefined;
		if (frontmatter.rules?.trim()) {
			rulesPath = resolve(cwd, frontmatter.rules.trim());
		}

		roles.push({
			name: frontmatter.name,
			description: frontmatter.description,
			who: frontmatter.who?.trim() || undefined,
			can: frontmatter.can?.trim() || undefined,
			when: frontmatter.when?.trim() || undefined,
			model: frontmatter.model?.trim() || undefined,
			tools: tools && tools.length > 0 ? tools : undefined,
			skills: skills && skills.length > 0 ? skills : undefined,
			rulesPath,
			systemPrompt: body.trim(),
			source,
			filePath,
		});
	}

	return roles;
}

function isDirectory(p: string): boolean {
	try {
		return statSync(p).isDirectory();
	} catch {
		return false;
	}
}

/** Resolve project roles directory (absolute). */
export function resolveProjectRolesDir(cwd: string, rolesDir: string): string {
	return resolve(cwd, rolesDir);
}

/** Discover roles from user and project dirs; project overrides user by name. */
export function discoverRoles(options: DiscoverRolesOptions): DiscoverRolesResult {
	const agentDir = options.agentDir ?? getAgentDir();
	const userRolesDir = join(agentDir, "roles");
	const projectRolesDir = resolveProjectRolesDir(options.cwd, options.rolesDir);

	const userRoles = loadRolesFromDir(userRolesDir, "user", options.cwd);
	const projectRoles = loadRolesFromDir(projectRolesDir, "project", options.cwd);

	const roleMap = new Map<string, RoleConfig>();
	for (const role of userRoles) {
		roleMap.set(role.name, role);
	}
	for (const role of projectRoles) {
		roleMap.set(role.name, role);
	}

	return {
		roles: Array.from(roleMap.values()),
		projectRolesDir: isDirectory(projectRolesDir) ? projectRolesDir : null,
		userRolesDir,
	};
}

export function getRoleByName(roles: RoleConfig[], name: string): RoleConfig | undefined {
	return roles.find((r) => r.name === name);
}

function resolveRolePresentation(role: RoleConfig): { who: string; can: string; when: string } {
	return {
		who: role.who?.trim() || `${role.name} — ${role.description}`,
		can: role.can?.trim() || role.description,
		when: role.when?.trim() || "When the delegated task matches this role's capabilities.",
	};
}

/** Compact list (legacy / debugging). */
export function formatRoleCatalog(roles: RoleConfig[], excludeName?: string): string {
	const listed = roles.filter((r) => r.name !== excludeName);
	if (listed.length === 0) {
		return "(no roles configured)";
	}
	return listed.map((r) => `- ${r.name}: ${r.description}`).join("\n");
}

/**
 * Room worker roster for PM task planning. Only includes roles assigned to the room.
 * Each entry introduces who / can do / when to assign.
 */
export function formatRoomRosterForPm(workerRoles: RoleConfig[]): string {
	if (workerRoles.length === 0) {
		return "(no worker roles are assigned to this room)";
	}
	return workerRoles
		.map((role) => {
			const p = resolveRolePresentation(role);
			return `### ${role.name}\n- Who: ${p.who}\n- Can do: ${p.can}\n- When to assign: ${p.when}`;
		})
		.join("\n\n");
}

import type {
	HubClientMessage,
	HubCommandResultMessage,
	HubModelInfo,
	HubModelsConfigPayload,
	HubRoleContentPayload,
	HubRoleSummaryPayload,
	HubRoomConfigPayload,
	HubRoomSummary,
	HubServerMessage,
} from "./protocol.ts";

export type MessageHandler = (msg: HubServerMessage) => void;

function uuidV4(): string {
	const c = globalThis.crypto as Crypto | undefined;
	if (c && typeof c.randomUUID === "function") return c.randomUUID();
	const bytes = new Uint8Array(16);
	if (c && typeof c.getRandomValues === "function") {
		c.getRandomValues(bytes);
	} else {
		for (let i = 0; i < 16; i++) bytes[i] = Math.floor(Math.random() * 256);
	}
	bytes[6] = (bytes[6]! & 0x0f) | 0x40;
	bytes[8] = (bytes[8]! & 0x3f) | 0x80;
	const hex: string[] = [];
	for (let i = 0; i < 16; i++) hex.push(bytes[i]!.toString(16).padStart(2, "0"));
	return `${hex.slice(0, 4).join("")}-${hex.slice(4, 6).join("")}-${hex.slice(6, 8).join("")}-${hex.slice(8, 10).join("")}-${hex.slice(10, 16).join("")}`;
}

type CommandResolver = {
	resolve: (data: unknown) => void;
	reject: (error: Error) => void;
};

export class HubClient {
	private ws: WebSocket | null = null;
	private handlers: MessageHandler[] = [];
	private readonly pendingCommands = new Map<string, CommandResolver>();
	private readonly hubUrl: string;
	private roomId: string;
	private readonly token: string;
	private readonly displayName: string;
	private joined = false;
	private socketOpenSettled = false;

	constructor(hubUrl: string, roomId: string, token: string, displayName: string) {
		this.hubUrl = hubUrl;
		this.roomId = roomId;
		this.token = token;
		this.displayName = displayName;
	}

	getRoomId(): string {
		return this.roomId;
	}

	isJoined(): boolean {
		return this.joined;
	}

	isSocketOpen(): boolean {
		return this.ws?.readyState === WebSocket.OPEN;
	}

	onMessage(handler: MessageHandler): () => void {
		this.handlers.push(handler);
		return () => {
			this.handlers = this.handlers.filter((h) => h !== handler);
		};
	}

	private resetMembership(): void {
		this.joined = false;
	}

	private notifyHandlers(msg: HubServerMessage): void {
		for (const h of this.handlers) {
			h(msg);
		}
	}

	private handleSocketClosed(): void {
		this.resetMembership();
		this.notifyHandlers({ type: "connection_lost" });
	}

	private closeExistingSocket(): void {
		if (!this.ws) {
			return;
		}
		const existing = this.ws;
		existing.onopen = null;
		existing.onmessage = null;
		existing.onerror = null;
		existing.onclose = null;
		if (existing.readyState === WebSocket.OPEN || existing.readyState === WebSocket.CONNECTING) {
			existing.close();
		}
		this.ws = null;
	}

	/** Open WebSocket only (no join). */
	openSocket(): Promise<void> {
		this.closeExistingSocket();
		this.socketOpenSettled = false;

		return new Promise((resolve, reject) => {
			let settled = false;
			const fail = (error: Error) => {
				if (settled) return;
				settled = true;
				reject(error);
			};

			const timeoutId = setTimeout(() => {
				fail(new Error("Connection timed out waiting for hub."));
				this.ws?.close();
			}, 30_000);

			this.ws = new WebSocket(this.hubUrl);
			this.ws.onopen = () => {
				if (!settled) {
					settled = true;
					this.socketOpenSettled = true;
					clearTimeout(timeoutId);
					resolve();
				}
			};
			this.ws.onmessage = (ev) => this.dispatchMessage(ev);
			this.ws.onerror = () => fail(new Error(`WebSocket error connecting to ${this.hubUrl}`));
			this.ws.onclose = (ev) => {
				clearTimeout(timeoutId);
				if (this.socketOpenSettled) {
					this.handleSocketClosed();
				}
				if (!settled) {
					fail(new Error(`WebSocket closed (${ev.code})`));
				}
			};
		});
	}

	connect(): Promise<void> {
		return this.openSocket().then(() => this.join(this.roomId));
	}

	reconnect(roomId: string): Promise<void> {
		return this.switchRoom(roomId);
	}

	leave(): Promise<void> {
		if (!this.joined) {
			return Promise.resolve();
		}
		if (!this.isSocketOpen()) {
			this.resetMembership();
			return Promise.resolve();
		}
		return new Promise((resolve) => {
			const timeoutId = setTimeout(() => {
				this.resetMembership();
				resolve();
			}, 30_000);

			const unsub = this.onMessage((msg) => {
				if (msg.type === "left") {
					clearTimeout(timeoutId);
					unsub();
					this.joined = false;
					resolve();
				}
				if (msg.type === "error" && msg.code === "not_joined") {
					clearTimeout(timeoutId);
					unsub();
					this.joined = false;
					resolve();
				}
			});

			this.send({ type: "leave" });
		});
	}

	async switchRoom(roomId: string): Promise<void> {
		if (this.joined) {
			try {
				await this.leave();
			} catch {
				this.resetMembership();
			}
		}
		if (!this.isSocketOpen()) {
			this.resetMembership();
			await this.openSocket();
		}
		await this.join(roomId);
	}

	join(roomId: string): Promise<void> {
		this.roomId = roomId;
		if (this.joined) {
			return Promise.reject(new Error("Already joined; call leave() first"));
		}
		if (!this.isSocketOpen()) {
			return Promise.reject(new Error("WebSocket is not open"));
		}
		return new Promise((resolve, reject) => {
			const timeoutId = setTimeout(() => {
				reject(new Error("Join timed out"));
			}, 120_000);

			const unsub = this.onMessage((msg) => {
				if (msg.type === "joined") {
					clearTimeout(timeoutId);
					unsub();
					this.joined = true;
					resolve();
				}
				if (
					msg.type === "error" &&
					(msg.code === "join_failed" || msg.code === "room_not_found" || msg.code === "already_joined")
				) {
					clearTimeout(timeoutId);
					unsub();
					reject(new Error(String(msg.message ?? msg.code)));
				}
			});

			this.send({
				type: "join",
				roomId: this.roomId,
				token: this.token,
				displayName: this.displayName,
			});
		});
	}

	private dispatchMessage(ev: MessageEvent): void {
		try {
			const msg = JSON.parse(String(ev.data)) as HubServerMessage;
			this.handleCommandResult(msg);
			this.notifyHandlers(msg);
		} catch {
			// ignore
		}
	}

	private handleCommandResult(msg: HubServerMessage): void {
		if (msg.type !== "command_result") return;
		const result = msg as HubCommandResultMessage;
		if (!result.id) return;
		const pending = this.pendingCommands.get(result.id);
		if (!pending) return;
		this.pendingCommands.delete(result.id);
		if (result.success) {
			pending.resolve(result.data);
		} else {
			pending.reject(new Error(result.error ?? `${result.command} failed`));
		}
	}

	private sendCommand<T>(message: HubClientMessage, timeoutMs = 30_000): Promise<T> {
		const id = uuidV4();
		return new Promise<T>((resolve, reject) => {
			const timer = setTimeout(() => {
				this.pendingCommands.delete(id);
				reject(new Error(`Command timed out: ${message.type}`));
			}, timeoutMs);

			this.pendingCommands.set(id, {
				resolve: (data) => {
					clearTimeout(timer);
					resolve(data as T);
				},
				reject: (error) => {
					clearTimeout(timer);
					reject(error);
				},
			});

			this.send({ ...message, id });
		});
	}

	send(msg: HubClientMessage): void {
		if (this.ws?.readyState === WebSocket.OPEN) {
			this.ws.send(JSON.stringify(msg));
		}
	}

	async listRooms(): Promise<HubRoomSummary[]> {
		const data = await this.sendCommand<{ rooms: HubRoomSummary[] }>({
			type: "list_rooms",
			token: this.token,
		});
		return data.rooms ?? [];
	}

	async createRoom(roomId: string, title?: string): Promise<void> {
		await this.sendCommand({
			type: "create_room",
			token: this.token,
			roomId,
			title,
		});
	}

	async deleteRoom(roomId: string, deleteFiles = true): Promise<void> {
		await this.sendCommand({
			type: "delete_room",
			token: this.token,
			roomId,
			deleteFiles,
		});
	}

	async getRoomConfig(roomId: string): Promise<HubRoomConfigPayload> {
		const data = await this.sendCommand<{ config: HubRoomConfigPayload }>({
			type: "get_room_config",
			token: this.token,
			roomId,
		});
		return data.config ?? {};
	}

	async setRoomConfig(roomId: string, config: HubRoomConfigPayload): Promise<HubRoomConfigPayload> {
		const data = await this.sendCommand<{ config: HubRoomConfigPayload }>({
			type: "set_room_config",
			token: this.token,
			roomId,
			config,
		});
		return data.config ?? config;
	}

	async addRoomRole(roleName: string, roomId = this.roomId): Promise<HubRoomConfigPayload> {
		const data = await this.sendCommand<{ config: HubRoomConfigPayload }>({
			type: "add_room_role",
			token: this.token,
			roomId,
			roleName,
		});
		return data.config ?? {};
	}

	async removeRoomRole(roleName: string, roomId = this.roomId): Promise<HubRoomConfigPayload> {
		const data = await this.sendCommand<{ config: HubRoomConfigPayload }>({
			type: "remove_room_role",
			token: this.token,
			roomId,
			roleName,
		});
		return data.config ?? {};
	}

	async listSkills(): Promise<Array<{ name: string; source: string; description?: string }>> {
		const data = await this.sendCommand<{ skills: Array<{ name: string; source: string; description?: string }> }>({
			type: "list_skills",
			token: this.token,
		});
		return data.skills ?? [];
	}

	async getSkillContent(name: string): Promise<{ name: string; source: string; filePath: string; content: string }> {
		return this.sendCommand({
			type: "get_skill_content",
			token: this.token,
			name,
		});
	}

	async clearRoomSession(roomId: string): Promise<void> {
		await this.sendCommand({
			type: "clear_room_session",
			token: this.token,
			roomId,
		});
	}

	async listRoles(): Promise<HubRoleSummaryPayload[]> {
		const data = await this.sendCommand<{ roles: HubRoleSummaryPayload[] }>({
			type: "list_roles",
			token: this.token,
		});
		return data.roles ?? [];
	}

	async getRole(name: string): Promise<HubRoleContentPayload> {
		return this.sendCommand<HubRoleContentPayload>({
			type: "get_role",
			token: this.token,
			name,
		});
	}

	async saveRole(name: string, content: string): Promise<HubRoleContentPayload> {
		return this.sendCommand<HubRoleContentPayload>({
			type: "save_role",
			token: this.token,
			name,
			content,
		});
	}

	async deleteRole(name: string): Promise<void> {
		await this.sendCommand({
			type: "delete_role",
			token: this.token,
			name,
		});
	}

	async getAvailableModels(): Promise<HubModelInfo[]> {
		const data = await this.sendCommand<{ models: HubModelInfo[] }>({ type: "get_available_models" });
		return data.models ?? [];
	}

	async getModelsConfig(): Promise<HubModelsConfigPayload> {
		return this.sendCommand<HubModelsConfigPayload>({ type: "get_models_config" });
	}

	async setRoleModel(
		roleName: string,
		provider: string | null,
		modelId: string | null,
	): Promise<HubModelsConfigPayload> {
		if (provider === null || modelId === null) {
			return this.sendCommand<HubModelsConfigPayload>({ type: "set_role_model", roleName });
		}
		return this.sendCommand<HubModelsConfigPayload>({
			type: "set_role_model",
			roleName,
			provider,
			modelId,
		});
	}

	async setModel(provider: string, modelId: string): Promise<void> {
		await this.sendCommand({ type: "set_model", provider, modelId });
	}

	async setProviderBaseUrl(provider: string, baseUrl: string): Promise<HubModelInfo[]> {
		const data = await this.sendCommand<{ models: HubModelInfo[] }>({
			type: "set_provider_base_url",
			provider,
			baseUrl,
		});
		return data.models ?? [];
	}

	prompt(
		message: string,
		options?: {
			images?: Array<{ type: "image"; data: string; mimeType: string }>;
		},
	): void {
		const payload: Record<string, unknown> = { type: "prompt", message };
		if (options?.images && options.images.length > 0) {
			payload.images = options.images;
		}
		this.send(payload);
	}

	extensionUiResponse(response: HubClientMessage): void {
		this.send(response);
	}

	disconnect(): void {
		this.resetMembership();
		this.socketOpenSettled = false;
		this.closeExistingSocket();
		for (const pending of this.pendingCommands.values()) {
			pending.reject(new Error("Disconnected"));
		}
		this.pendingCommands.clear();
	}
}

export function defaultWsUrl(): string {
	const proto = location.protocol === "https:" ? "wss:" : "ws:";
	return `${proto}//${location.host}/ws`;
}

