function getFinalAssistantText(messages: Message[]): string {
	for (let i = messages.length - 1; i >= 0; i--) {
		const msg = messages[i];
		if (msg.role === "assistant") {
			for (const part of msg.content) {
				if (part.type === "text") {
					return part.text;
				}
			}
		}
	}
	return "";
}

function writeTempPromptFile(agentName: string, prompt: string): { dir: string; filePath: string } {
	const tmpDir = mkdtempSync(path.join(os.tmpdir(), "pi-hub-role-"));
	const safeName = agentName.replace(/[^\w.-]+/g, "_");
	const filePath = path.join(tmpDir, `prompt-${safeName}.md`);
	writeFileSync(filePath, prompt, { encoding: "utf-8", mode: 0o600 });
	return { dir: tmpDir, filePath };
}

function resolveAppendSystemPrompt(role: RoleConfig | ResolvedRoleConfig): string {
	if ("resolvedRulesText" in role && role.resolvedRulesText) {
		return role.resolvedRulesText;
	}
	if (role.rulesPath && existsSync(role.rulesPath)) {
		try {
			return readFileSync(role.rulesPath, "utf-8").trim();
		} catch {
			// fall through
		}
	}
	return role.systemPrompt;
}

export async function runRoleSubprocess(options: RunRoleOptions): Promise<RunRoleResult> {
	const { role, task, cwd, agentDir, contextPrefix, signal, roomSkillsDir } = options;

	const args: string[] = ["--mode", "json", "-p", "--no-session"];
	if (role.model) {
		args.push("--model", role.model);
	}
	if (role.tools && role.tools.length > 0) {
		args.push("--tools", role.tools.join(","));
	}

	const skillNames = "resolvedSkills" in role && role.resolvedSkills ? role.resolvedSkills : role.skills;
	const skillPaths = skillNames ? resolveSkillPaths(cwd, agentDir, skillNames, roomSkillsDir) : [];
	for (const skillPath of skillPaths) {
		args.push("--skill", skillPath);
	}

	const tmpPromptDir: string | null = null;
	const tmpPromptPath: string | null = null;
	let tmpAppendDir: string | null = null;
	let tmpAppendPath: string | null = null;

	const messages: Message[] = [];
	let stderr = "";
	let errorMessage: string | undefined;

	try {
		const appendText = resolveAppendSystemPrompt(role);
		if (appendText) {
			const tmp = writeTempPromptFile(`${role.name}-rules`, appendText);
			tmpAppendDir = tmp.dir;
			tmpAppendPath = tmp.filePath;
			args.push("--append-system-prompt", tmpAppendPath);
		}

		const userTask = contextPrefix ? `${contextPrefix}\n\nTask: ${task}` : `Task: ${task}`;
		args.push(userTask);

		const invocation = getPiInvocation(args);
		const modelLabel = role.model?.trim() || "(session default)";
		console.log(`[pi-hub] Role "${role.name}" subprocess model=${modelLabel}`);

		const exitCode = await new Promise<number>((resolve, reject) => {
			const proc = spawn(invocation.command, invocation.args, {
				cwd,
				shell: false,
				stdio: ["ignore", "pipe", "pipe"],
			});

			let buffer = "";

			const processLine = (line: string) => {
				if (!line.trim()) return;
				let event: { type?: string; message?: Message };
				try {
					event = JSON.parse(line) as { type?: string; message?: Message };
				} catch {
					return;
				}

				if (event.type === "message_end" && event.message) {
					messages.push(event.message);
					if (event.message.role === "assistant") {
						if (event.message.errorMessage) {
							errorMessage = event.message.errorMessage;
						}
					}
				}
			};

			proc.stdout.on("data", (data) => {
				buffer += data.toString();
				const lines = buffer.split("\n");
				buffer = lines.pop() ?? "";
				for (const line of lines) {
					processLine(line);
				}
			});

			proc.stderr.on("data", (data) => {
				stderr += data.toString();
			});

			proc.on("close", (code) => {
				if (buffer.trim()) {
					processLine(buffer);
				}
				resolve(code ?? 0);
			});

			proc.on("error", (err) => {
				const detail = err instanceof Error ? err.message : String(err);
				reject(
					new Error(
						`Role "${role.name}" failed to start (model=${modelLabel}): ${detail}. Command: ${invocation.command}`,
					),
				);
			});

			if (signal) {
				const killProc = () => {
					proc.kill("SIGTERM");
					setTimeout(() => {
						if (!proc.killed) {
							proc.kill("SIGKILL");
						}
					}, 5000);
				};
				if (signal.aborted) {
					killProc();
				} else {
					signal.addEventListener("abort", killProc, { once: true });
				}
			}
		});

		const output = getFinalAssistantText(messages) || stderr || "(no output)";
		return {
			exitCode,
			output,
			stderr,
			errorMessage,
		};
	} finally {
		if (tmpAppendPath) {
			try {
				rmSync(tmpAppendPath, { force: true });
			} catch {
				/* ignore */
			}
		}
		if (tmpAppendDir) {
			try {
				rmSync(tmpAppendDir, { recursive: true, force: true });
			} catch {
				/* ignore */
			}
		}
		if (tmpPromptPath) {
			try {
				rmSync(tmpPromptPath, { force: true });
			} catch {
				/* ignore */
			}
		}
		if (tmpPromptDir) {
			try {
				rmSync(tmpPromptDir, { recursive: true, force: true });
			} catch {
				/* ignore */
			}
		}
	}
}

export type MentionKind = "role" | "user";

export interface MentionTarget {
	kind: MentionKind;
	name: string;
	label: string;
	hint?: string;
}

export interface MentionComposerOptions {
	input: HTMLTextAreaElement;
	menu: HTMLElement;
	getTargets: () => MentionTarget[];
}

interface ActiveMentionQuery {
	start: number;
	query: string;
}

function getActiveMentionQuery(input: HTMLTextAreaElement): ActiveMentionQuery | null {
	const cursor = input.selectionStart ?? input.value.length;
	const before = input.value.slice(0, cursor);
	const at = before.lastIndexOf("@");
	if (at < 0) {
		return null;
	}
	const between = before.slice(at + 1);
	if (between.includes(" ") || between.includes("\n")) {
		return null;
	}
	return { start: at, query: between.toLowerCase() };
}

function filterTargets(targets: MentionTarget[], query: string): MentionTarget[] {
	if (!query) {
		return targets;
	}
	return targets.filter(
		(t) =>
			t.name.toLowerCase().includes(query) ||
			t.label.toLowerCase().includes(query) ||
			(t.hint?.toLowerCase().includes(query) ?? false),
	);
}

export function setupMentionComposer(options: MentionComposerOptions): () => void {
	const { input, menu, getTargets } = options;
	let activeIndex = 0;
	let visibleItems: MentionTarget[] = [];

	function hideMenu(): void {
		menu.classList.add("hidden");
		menu.innerHTML = "";
		visibleItems = [];
		activeIndex = 0;
	}

	function renderMenu(items: MentionTarget[]): void {
		menu.innerHTML = "";
		if (items.length === 0) {
			hideMenu();
			return;
		}
		visibleItems = items;
		for (let i = 0; i < items.length; i++) {
			const item = items[i]!;
			const btn = document.createElement("button");
			btn.type = "button";
			btn.className = "mention-menu-item";
			if (i === activeIndex) {
				btn.classList.add("mention-menu-item-active");
			}
			const kind = document.createElement("span");
			kind.className = `mention-menu-kind mention-menu-kind-${item.kind}`;
			kind.textContent = item.kind === "role" ? "role" : "user";
			const label = document.createElement("span");
			label.className = "mention-menu-label";
			label.textContent = item.label;
			btn.append(kind, label);
			if (item.hint) {
				const hint = document.createElement("span");
				hint.className = "mention-menu-hint";
				hint.textContent = item.hint;
				btn.appendChild(hint);
			}
			btn.addEventListener("mousedown", (e) => {
				e.preventDefault();
				applyMention(item.name);
			});
			menu.appendChild(btn);
		}
		menu.classList.remove("hidden");
	}

	function applyMention(name: string): void {
		const query = getActiveMentionQuery(input);
		if (!query) {
			hideMenu();
			return;
		}
		const cursor = input.selectionStart ?? input.value.length;
		const before = input.value.slice(0, query.start);
		const after = input.value.slice(cursor);
		const insert = `@${name} `;
		input.value = `${before}${insert}${after}`;
		const nextCursor = before.length + insert.length;
		input.setSelectionRange(nextCursor, nextCursor);
		input.focus();
		hideMenu();
		input.dispatchEvent(new Event("input", { bubbles: true }));
	}

	function refreshMenu(): void {
		const query = getActiveMentionQuery(input);
		if (!query) {
			hideMenu();
			return;
		}
		activeIndex = 0;
		renderMenu(filterTargets(getTargets(), query.query));
	}

	function onKeyDown(e: KeyboardEvent): void {
		if (menu.classList.contains("hidden") || visibleItems.length === 0) {
			return;
		}
		if (e.key === "ArrowDown") {
			e.preventDefault();
			activeIndex = (activeIndex + 1) % visibleItems.length;
			renderMenu(visibleItems);
			return;
		}
		if (e.key === "ArrowUp") {
			e.preventDefault();
			activeIndex = (activeIndex - 1 + visibleItems.length) % visibleItems.length;
			renderMenu(visibleItems);
			return;
		}
		if (e.key === "Enter" || e.key === "Tab") {
			const picked = visibleItems[activeIndex];
			if (picked) {
				e.preventDefault();
				applyMention(picked.name);
			}
			return;
		}
		if (e.key === "Escape") {
			e.preventDefault();
			hideMenu();
		}
	}

	input.addEventListener("input", refreshMenu);
	input.addEventListener("click", refreshMenu);
	input.addEventListener("keydown", onKeyDown);
	document.addEventListener("click", (e) => {
		if (e.target === input || menu.contains(e.target as Node)) {
			return;
		}
		hideMenu();
	});

	return hideMenu;
}

import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { prepareRoomConfigPatch, type ValidateRoomRolesOptions } from "./room-roles.ts";

const MAX_ROOM_ID_LENGTH = 64;
/** Unicode letters (e.g. Chinese), numbers, hyphen, underscore. */
const ROOM_ID_PATTERN = /^[\p{L}\p{N}_-][\p{L}\p{N}_-]{0,63}$/u;
const SESSION_FILENAME = "session.jsonl";
const CONFIG_FILENAME = "config.json";

export interface RoomRoleOverride {
	skills?: string[];
	rules?: string;
	tools?: string[];
	model?: string;
}

export interface RoomConfigFile {
	/** Role names assigned to this room (ordered, unique). */
	roleNames?: string[];
	skills?: string[];
	rules?: string;
	roleOverrides?: Record<string, RoomRoleOverride>;
	rolesEnabled?: boolean;
}

export interface RoomIndexEntry {
	roomId: string;
	title?: string;
	createdAt: string;
	updatedAt: string;
	/** Path relative to cwd or absolute. */
	sessionFile: string;
}

export interface RoomsIndexFile {
	rooms: RoomIndexEntry[];
}

export class RoomRegistryError extends Error {
	readonly code: string;

	constructor(message: string, code: string) {
		super(message);
		this.name = "RoomRegistryError";
		this.code = code;
	}
}

function mergeRoomConfigSimple(patch: RoomConfigFile, current: RoomConfigFile): RoomConfigFile {
	return {
		...current,
		...patch,
		roleOverrides: patch.roleOverrides !== undefined ? patch.roleOverrides : current.roleOverrides,
	};
}

export function validateRoomId(roomId: string): string {
	const trimmed = roomId.trim();
	if (!trimmed) {
		throw new RoomRegistryError("roomId is required", "invalid_room_id");
	}
	if (trimmed.length > MAX_ROOM_ID_LENGTH) {
		throw new RoomRegistryError(`roomId must be at most ${MAX_ROOM_ID_LENGTH} characters`, "invalid_room_id");
	}
	if (trimmed.includes("..") || trimmed.includes("/") || trimmed.includes("\\")) {
		throw new RoomRegistryError("roomId must not contain path separators", "invalid_room_id");
	}
	if (/[\u0000-\u001f\u007f]/.test(trimmed)) {
		throw new RoomRegistryError("roomId must not contain control characters", "invalid_room_id");
	}
	if (!ROOM_ID_PATTERN.test(trimmed)) {
		throw new RoomRegistryError(
			"roomId must be 1-64 chars: letters (including Chinese), digits, hyphen, or underscore",
			"invalid_room_id",
		);
	}
	return trimmed;
}

export class RoomRegistry {
	private readonly cwd: string;
	private readonly hubDir: string;
	private readonly roomsDir: string;
	private readonly indexPath: string;

	constructor(cwd: string) {
		this.cwd = resolve(cwd);
		this.hubDir = join(this.cwd, ".pi", "hub");
		this.roomsDir = join(this.hubDir, "rooms");
		this.indexPath = join(this.hubDir, "rooms.json");
	}

	getHubDir(): string {
		return this.hubDir;
	}

	private ensureHubDir(): void {
		if (!existsSync(this.hubDir)) {
			mkdirSync(this.hubDir, { recursive: true });
		}
	}

	private readIndex(): RoomsIndexFile {
		this.ensureHubDir();
		if (!existsSync(this.indexPath)) {
			return { rooms: [] };
		}
		try {
			const raw = readFileSync(this.indexPath, "utf8");
			const parsed = JSON.parse(raw) as RoomsIndexFile;
			return { rooms: Array.isArray(parsed.rooms) ? parsed.rooms : [] };
		} catch {
			return { rooms: [] };
		}
	}

	private writeIndex(index: RoomsIndexFile): void {
		this.ensureHubDir();
		writeFileSync(this.indexPath, `${JSON.stringify(index, null, 2)}\n`, "utf8");
	}

	private roomDir(roomId: string): string {
		return join(this.roomsDir, validateRoomId(roomId));
	}

	private defaultSessionRelativePath(roomId: string): string {
		return join(".pi", "hub", "rooms", roomId, SESSION_FILENAME);
	}

	listRooms(): RoomIndexEntry[] {
		return this.readIndex().rooms;
	}

	getRoom(roomId: string): RoomIndexEntry | undefined {
		const id = validateRoomId(roomId);
		return this.readIndex().rooms.find((r) => r.roomId === id);
	}

	hasRoom(roomId: string): boolean {
		return this.getRoom(roomId) !== undefined;
	}

	/** Create registry entry and room directory. Does not create session file until resolveSessionPath. */
	createRoom(roomId: string, options?: { title?: string }): RoomIndexEntry {
		const id = validateRoomId(roomId);
		const index = this.readIndex();
		if (index.rooms.some((r) => r.roomId === id)) {
			throw new RoomRegistryError(`Room already exists: ${id}`, "room_exists");
		}

		const now = new Date().toISOString();
		const sessionFile = this.defaultSessionRelativePath(id);
		const entry: RoomIndexEntry = {
			roomId: id,
			title: options?.title?.trim() || undefined,
			createdAt: now,
			updatedAt: now,
			sessionFile,
		};

		const dir = this.roomDir(id);
		mkdirSync(dir, { recursive: true });
		if (!existsSync(join(dir, CONFIG_FILENAME))) {
			writeFileSync(join(dir, CONFIG_FILENAME), "{}\n", "utf8");
		}

		index.rooms.push(entry);
		this.writeIndex(index);
		return entry;
	}

	/** Ensure default room exists when index is empty. */
	ensureDefaultRoom(defaultRoomId: string): RoomIndexEntry {
		const id = validateRoomId(defaultRoomId);
		const existing = this.getRoom(id);
		if (existing) {
			return existing;
		}
		const index = this.readIndex();
		if (index.rooms.length > 0) {
			throw new RoomRegistryError(`Default room "${id}" not in registry`, "room_not_found");
		}
		return this.createRoom(id, { title: "Default" });
	}

	deleteRoom(roomId: string, options?: { deleteFiles?: boolean }): void {
		const id = validateRoomId(roomId);
		const deleteFiles = options?.deleteFiles !== false;
		const index = this.readIndex();
		const next = index.rooms.filter((r) => r.roomId !== id);
		if (next.length === index.rooms.length) {
			throw new RoomRegistryError(`Room not found: ${id}`, "room_not_found");
		}
		this.writeIndex({ rooms: next });

		if (deleteFiles) {
			const dir = this.roomDir(id);
			if (existsSync(dir)) {
				rmSync(dir, { recursive: true, force: true });
			}
		}
	}

	/** Absolute path to session JSONL from registry (file may not exist yet). */
	getSessionPath(roomId: string): string {
		const id = validateRoomId(roomId);
		const entry = this.getRoom(id);
		if (!entry) {
			throw new RoomRegistryError(`Room not found: ${id}. Create it with create_room first.`, "room_not_found");
		}

		const absPath = resolve(this.cwd, entry.sessionFile);
		const dir = resolve(absPath, "..");
		if (!existsSync(dir)) {
			mkdirSync(dir, { recursive: true });
		}
		return absPath;
	}

	/** Update session file path after SessionManager creates a new file in the room directory. */
	updateSessionFile(roomId: string, absoluteSessionPath: string): void {
		const id = validateRoomId(roomId);
		const index = this.readIndex();
		const entry = index.rooms.find((r) => r.roomId === id);
		if (!entry) {
			throw new RoomRegistryError(`Room not found: ${id}`, "room_not_found");
		}
		const rel = absoluteSessionPath.startsWith(this.cwd)
			? absoluteSessionPath.slice(this.cwd.length).replace(/^[/\\]/, "")
			: absoluteSessionPath;
		entry.sessionFile = rel.split("\\").join("/");
		entry.updatedAt = new Date().toISOString();
		this.writeIndex(index);
	}

	touchRoom(roomId: string): void {
		const id = validateRoomId(roomId);
		const index = this.readIndex();
		const entry = index.rooms.find((r) => r.roomId === id);
		if (!entry) {
			return;
		}
		entry.updatedAt = new Date().toISOString();
		this.writeIndex(index);
	}

	loadRoomConfig(roomId: string): RoomConfigFile {
		const id = validateRoomId(roomId);
		const path = join(this.roomDir(id), CONFIG_FILENAME);
		if (!existsSync(path)) {
			return {};
		}
		try {
			const raw = readFileSync(path, "utf8");
			return JSON.parse(raw) as RoomConfigFile;
		} catch {
			return {};
		}
	}

	saveRoomConfig(roomId: string, patch: RoomConfigFile, options?: ValidateRoomRolesOptions): RoomConfigFile {
		const id = validateRoomId(roomId);
		if (!this.hasRoom(id)) {
			throw new RoomRegistryError(`Room not found: ${id}`, "room_not_found");
		}
		const dir = this.roomDir(id);
		mkdirSync(dir, { recursive: true });
		const current = this.loadRoomConfig(id);
		const merged = options ? prepareRoomConfigPatch(patch, current, options) : mergeRoomConfigSimple(patch, current);
		writeFileSync(join(dir, CONFIG_FILENAME), `${JSON.stringify(merged, null, 2)}\n`, "utf8");
		this.touchRoom(id);
		return merged;
	}

	getRoomSkillsDir(roomId: string): string {
		const id = validateRoomId(roomId);
		return join(this.roomDir(id), "skills");
	}
}

import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { getAgentDir, parseFrontmatter } from "@earendil-works/pi-coding-agent";
import type { HubRoleContentPayload, HubRoleSummaryPayload } from "../protocol.ts";
import { discoverRoles, resolveProjectRolesDir } from "./discovery.ts";
import type { RoleConfig } from "./types.ts";

export class RoleStoreError extends Error {
	readonly code: string;

	constructor(message: string, code: string) {
		super(message);
		this.name = "RoleStoreError";
		this.code = code;
	}
}

function roleToSummary(role: RoleConfig): HubRoleSummaryPayload {
	const preview = role.systemPrompt.length > 200 ? `${role.systemPrompt.slice(0, 200)}...` : role.systemPrompt;
	return {
		name: role.name,
		description: role.description,
		who: role.who,
		can: role.can,
		when: role.when,
		source: role.source,
		filePath: role.filePath,
		model: role.model,
		tools: role.tools,
		skills: role.skills,
		rulesPath: role.rulesPath,
		systemPromptPreview: preview,
	};
}

export function listRoleSummaries(cwd: string, rolesDir: string): HubRoleSummaryPayload[] {
	const discovery = discoverRoles({ cwd, rolesDir });
	return discovery.roles.map(roleToSummary);
}

export function getRoleContent(cwd: string, rolesDir: string, name: string): HubRoleContentPayload {
	const discovery = discoverRoles({ cwd, rolesDir });
	const role = discovery.roles.find((r) => r.name === name);
	if (!role) {
		throw new RoleStoreError(`Role not found: ${name}`, "role_not_found");
	}
	const content = readFileSync(role.filePath, "utf8");
	return {
		name: role.name,
		source: role.source,
		filePath: role.filePath,
		content,
	};
}

function validateRoleContent(content: string): { name: string; description: string } {
	const { frontmatter } = parseFrontmatter<Record<string, string>>(content);
	const name = frontmatter.name?.trim();
	const description = frontmatter.description?.trim();
	if (!name || !description) {
		throw new RoleStoreError("Role markdown must include frontmatter name and description", "invalid_role");
	}
	return { name, description };
}

function isPathUnderRolesDir(filePath: string, allowedDirs: string[]): boolean {
	const normalized = filePath.replace(/\\/g, "/");
	return allowedDirs.some((dir) => {
		const base = dir.replace(/\\/g, "/");
		return normalized === base || normalized.startsWith(`${base}/`);
	});
}

export function saveRoleContent(cwd: string, rolesDir: string, name: string, content: string): HubRoleContentPayload {
	const parsed = validateRoleContent(content);
	if (parsed.name !== name.trim()) {
		throw new RoleStoreError(
			`Frontmatter name "${parsed.name}" does not match requested name "${name}"`,
			"invalid_role",
		);
	}

	const agentDir = getAgentDir();
	const userRolesDir = join(agentDir, "roles");
	const projectRolesDir = resolveProjectRolesDir(cwd, rolesDir);

	const discovery = discoverRoles({ cwd, rolesDir });
	const existing = discovery.roles.find((r) => r.name === name);

	let filePath: string;
	let source: "user" | "project";

	if (existing) {
		filePath = existing.filePath;
		source = existing.source;
		if (!isPathUnderRolesDir(filePath, [userRolesDir, projectRolesDir])) {
			throw new RoleStoreError("Role file is outside allowed directories", "invalid_role");
		}
	} else {
		mkdirSync(projectRolesDir, { recursive: true });
		filePath = join(projectRolesDir, `${name}.md`);
		source = "project";
	}

	writeFileSync(filePath, content, "utf8");
	return { name, source, filePath, content };
}

export function deleteRoleFile(cwd: string, rolesDir: string, name: string, options?: { pmRole?: string }): void {
	if (options?.pmRole && name === options.pmRole) {
		throw new RoleStoreError(`Cannot delete PM role "${name}"`, "invalid_role");
	}

	const discovery = discoverRoles({ cwd, rolesDir });
	const role = discovery.roles.find((r) => r.name === name);
	if (!role) {
		throw new RoleStoreError(`Role not found: ${name}`, "role_not_found");
	}

	const agentDir = getAgentDir();
	const userRolesDir = join(agentDir, "roles");
	const projectRolesDir = resolveProjectRolesDir(cwd, rolesDir);
	if (!isPathUnderRolesDir(role.filePath, [userRolesDir, projectRolesDir])) {
		throw new RoleStoreError("Role file is outside allowed directories", "invalid_role");
	}

	if (!existsSync(role.filePath)) {
		throw new RoleStoreError(`Role file missing: ${role.filePath}`, "role_not_found");
	}
	rmSync(role.filePath, { force: true });
}

import { createReadStream, existsSync, statSync } from "node:fs";
import { createServer } from "node:http";
import { dirname, extname, join, normalize } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));

const MIME: Record<string, string> = {
	".html": "text/html; charset=utf-8",
	".js": "application/javascript; charset=utf-8",
	".css": "text/css; charset=utf-8",
	".json": "application/json; charset=utf-8",
	".svg": "image/svg+xml",
	".png": "image/png",
	".ico": "image/x-icon",
};

export interface HttpServerOptions {
	publicDir: string;
}

export function createHttpServer(options: HttpServerOptions): ReturnType<typeof createServer> {
	const publicRoot = normalize(options.publicDir);

	const server = createServer((req, res) => {
		const url = new URL(req.url ?? "/", "http://localhost");

		if (url.pathname === "/health") {
			res.writeHead(200, { "Content-Type": "application/json" });
			res.end(JSON.stringify({ ok: true }));
			return;
		}

		let filePath = url.pathname === "/" ? "/index.html" : url.pathname;
		const resolved = normalize(join(publicRoot, filePath));
		if (!resolved.startsWith(publicRoot)) {
			res.writeHead(403);
			res.end("Forbidden");
			return;
		}

		if (!existsSync(resolved) || statSync(resolved).isDirectory()) {
			const indexFallback = join(publicRoot, "index.html");
			if (existsSync(indexFallback)) {
				filePath = "/index.html";
			} else {
				res.writeHead(404);
				res.end("Not found");
				return;
			}
		}

		const finalPath = filePath === "/index.html" && !existsSync(resolved) ? join(publicRoot, "index.html") : resolved;
		const ext = extname(finalPath);
		res.writeHead(200, { "Content-Type": MIME[ext] ?? "application/octet-stream" });
		createReadStream(finalPath).pipe(res);
	});

	return server;
}

export function defaultPublicDir(): string {
	return join(__dirname, "public");
}

import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import type { RoomConfigFile, RoomRoleOverride } from "../room-registry.ts";
import type { RoleConfig } from "./types.ts";

export interface ResolvedRoleConfig extends RoleConfig {
	/** Merged skill names for subprocess. */
	resolvedSkills?: string[];
	/** Resolved append-system-prompt text. */
	resolvedRulesText: string;
}

function parseRulesText(rules: string | undefined, cwd: string): string {
	if (!rules?.trim()) {
		return "";
	}
	const trimmed = rules.trim();
	const asPath = resolve(cwd, trimmed);
	if (existsSync(asPath)) {
		try {
			return readFileSync(asPath, "utf-8").trim();
		} catch {
			return trimmed;
		}
	}
	return trimmed;
}

function mergeSkills(...lists: (string[] | undefined)[]): string[] {
	const seen = new Set<string>();
	const out: string[] = [];
	for (const list of lists) {
		if (!list) continue;
		for (const name of list) {
			const t = name.trim();
			if (t && !seen.has(t)) {
				seen.add(t);
				out.push(t);
			}
		}
	}
	return out;
}

function applyOverride(base: RoleConfig, override: RoomRoleOverride | undefined, cwd: string): ResolvedRoleConfig {
	const skills = mergeSkills(base.skills, override?.skills);
	const tools = override?.tools?.length ? override.tools : base.tools;
	const model = override?.model?.trim() || base.model;

	let resolvedRulesText = parseRulesText(override?.rules, cwd);
	if (!resolvedRulesText) {
		if (base.rulesPath && existsSync(base.rulesPath)) {
			try {
				resolvedRulesText = readFileSync(base.rulesPath, "utf-8").trim();
			} catch {
				resolvedRulesText = base.systemPrompt;
			}
		} else {
			resolvedRulesText = base.systemPrompt;
		}
	}

	return {
		...base,
		model,
		tools,
		skills: skills.length > 0 ? skills : undefined,
		resolvedSkills: skills.length > 0 ? skills : undefined,
		resolvedRulesText,
	};
}

/** Merge room config, role file, and per-role overrides. */
export function resolveRoleForRoom(role: RoleConfig, roomConfig: RoomConfigFile, cwd: string): ResolvedRoleConfig {
	const roomRulesPrefix = parseRulesText(roomConfig.rules, cwd);
	const override = roomConfig.roleOverrides?.[role.name];
	const merged = applyOverride(role, override, cwd);

	const roomSkills = roomConfig.skills;
	const skills = mergeSkills(roomSkills, merged.skills);

	let resolvedRulesText = merged.resolvedRulesText;
	if (roomRulesPrefix) {
		resolvedRulesText = roomRulesPrefix + (resolvedRulesText ? `\n\n${resolvedRulesText}` : "");
	}

	return {
		...merged,
		skills: skills.length > 0 ? skills : undefined,
		resolvedSkills: skills.length > 0 ? skills : undefined,
		resolvedRulesText,
	};
}

export function resolveRolesForRoom(
	roles: RoleConfig[],
	roomConfig: RoomConfigFile,
	cwd: string,
): ResolvedRoleConfig[] {
	return roles.map((r) => resolveRoleForRoom(r, roomConfig, cwd));
}

import { existsSync, writeFileSync } from "node:fs";
import { type HubConfigFile, loadConfigFile, projectConfigPath } from "./config.ts";
import type { HubModelInfo } from "./model-info.ts";
import type { RoleConfig } from "./roles/types.ts";

/** Parsed model reference: provider + model id. */
export interface ModelRef {
	provider: string;
	modelId: string;
}

export function formatModelRef(ref: ModelRef): string {
	return `${ref.provider}/${ref.modelId}`;
}

/** Parse "provider/modelId" (first slash separates provider from id). */
export function parseModelRef(value: string): ModelRef | undefined {
	const trimmed = value.trim();
	const slash = trimmed.indexOf("/");
	if (slash <= 0 || slash >= trimmed.length - 1) {
		return undefined;
	}
	return {
		provider: trimmed.slice(0, slash),
		modelId: trimmed.slice(slash + 1),
	};
}

export function modelRefMatchesInfo(ref: ModelRef, model: HubModelInfo): boolean {
	return model.provider === ref.provider && model.id === ref.modelId;
}

/** Filter registry models to catalog entries that exist; empty catalog returns all. */
export function filterModelsByCatalog(models: HubModelInfo[], catalog: string[]): HubModelInfo[] {
	if (catalog.length === 0) {
		return models;
	}
	const refs = catalog.map(parseModelRef).filter((r): r is ModelRef => r !== undefined);
	if (refs.length === 0) {
		return models;
	}
	return models.filter((m) => refs.some((r) => modelRefMatchesInfo(r, m)));
}

export function applyRoleModelOverrides(roles: RoleConfig[], overrides: Record<string, string>): RoleConfig[] {
	return roles.map((role) => {
		const override = overrides[role.name];
		if (!override?.trim()) {
			return role;
		}
		return { ...role, model: override.trim() };
	});
}

export interface HubRoleModelEntry {
	name: string;
	description: string;
	/** Configured model ref (provider/id) or undefined. */
	modelRef?: string;
	/** From role markdown frontmatter when no override. */
	fileModelRef?: string;
}

export function buildRoleModelEntries(roles: RoleConfig[], overrides: Record<string, string>): HubRoleModelEntry[] {
	return roles.map((role) => {
		const override = overrides[role.name]?.trim();
		const fileModel = role.model?.trim();
		return {
			name: role.name,
			description: role.description,
			modelRef: override || fileModel || undefined,
			fileModelRef: fileModel || undefined,
		};
	});
}

/** Merge role model override into project .pi/hub.json and return updated overrides map. */
export function persistRoleModelOverride(
	cwd: string,
	roleName: string,
	modelRef: string | null,
): Record<string, string> {
	const path = projectConfigPath(cwd);
	const existing: HubConfigFile = existsSync(path) ? loadConfigFile(path) : {};
	const roleModels = { ...(existing.models?.roleModels ?? {}) };
	if (modelRef === null || modelRef.trim() === "") {
		delete roleModels[roleName];
	} else {
		roleModels[roleName] = modelRef.trim();
	}
	const next: HubConfigFile = {
		...existing,
		models: {
			...existing.models,
			roleModels,
		},
	};
	writeFileSync(path, `${JSON.stringify(next, null, 2)}\n`, "utf8");
	return roleModels;
}
